-- Listage de la structure de la table projet_airid_africa_db. airid_departements
CREATE TABLE IF NOT EXISTS `airid_departements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nom_departement` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `description_accueil` text COLLATE utf8mb4_unicode_ci,
  `photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `chef_departement` int DEFAULT NULL,
  `afficher_menu` tinyint(1) NOT NULL DEFAULT '1',
  `afficher_accueil` tinyint(1) NOT NULL DEFAULT '1',
  `niveau_hierarchie` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `airid_departements_chef_departement_index` (`chef_departement`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Listage des données de la table projet_airid_africa_db.airid_departements : ~7 rows (environ)
INSERT INTO `airid_departements` (`id`, `nom_departement`, `description`, `description_accueil`, `photo`, `chef_departement`, `afficher_menu`, `afficher_accueil`, `niveau_hierarchie`, `created_at`, `updated_at`) VALUES
	(1, 'Board Of Trustees', 'A Board of Trustees is a governing body responsible for overseeing the management and strategic direction of an organization, including laboratories, educational institutions, non-profits, and other entities.', NULL, 'board_trustees.jpg', 1, 0, 0, 2, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(2, 'Administration and Finance', 'The Administration and Finance department in a laboratory plays a fundamental role in ensuring the smooth operation of the institution by managing various administrative, financial, and logistical functions. Here are some key roles and responsibilities:<br>\r\n\r\n<strong>Financial Management: </strong>Handling budgeting, financial planning, and accounting. This involves managing funds, monitoring expenses, and ensuring compliance with financial regulations and policies.<br>\r\n\r\n<strong>Procurement and Supplies:</strong> Overseeing the procurement process for equipment, supplies, and services necessary for research activities. This includes negotiating contracts, managing vendor relationships, and maintaining inventory.<br>\r\n\r\n<strong>Payroll and Human Resources:</strong> Managing payroll, benefits, and employee records. They may handle hiring processes, onboard new staff, manage personnel policies, and coordinate training programs.<br>\r\n\r\n<strong>Facilities Management:</strong> Maintaining and managing laboratory facilities, infrastructure, and equipment. This includes ensuring proper maintenance, safety protocols, and compliance with health and safety regulations.<br>\r\n\r\n<strong>Grants and Contracts Administration:</strong> Assisting researchers in the preparation and management of grants and contracts. This involves navigating funding opportunities, preparing proposals, and overseeing compliance with grant requirements.<br>\r\n\r\n<strong>Administrative Support:</strong> Providing administrative support to various departments within the laboratory. This includes managing schedules, organizing meetings, handling correspondence, and facilitating communication among different teams.<br>\r\n\r\n<strong>Policy Development and Compliance: </strong>Developing and implementing administrative policies and procedures. Ensuring compliance with institutional, governmental, and regulatory policies relevant to the laboratory\'s operations.<br>\r\n\r\n<strong>Reporting and Analysis:</strong> Generating financial reports, analyzing data, and providing insights to aid decision-making. This includes assessing financial performance, forecasting, and presenting information to management or stakeholders.<br>\r\n\r\n<strong>Strategic Planning and Resource Allocation:</strong> Collaborating with leadership in strategic planning, resource allocation, and long-term financial planning. This involves aligning financial resources with the laboratory\'s goals and priorities.<br>\r\n\r\n<strong>Risk Management:</strong> Identifying and mitigating financial and operational risks. This includes developing contingency plans, ensuring compliance with risk management protocols, and maintaining insurance coverage.\r\n<br>\r\nThe Administration and Finance department acts as a backbone for the laboratory, ensuring efficient financial operations, regulatory compliance, and effective administrative support to facilitate the institution\'s research and scientific endeavors.', 'Our department that is specialized in administrative and financial tasks.', 'admin.jpg', 4, 1, 1, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(3, 'Research Programmes', 'This department plays a crucial role in overseeing and managing the various research activities conducted within the institution. Some of its key responsibilities include:<br/>\r\n\r\n\r\nProgram Development: Designing, developing, and implementing research programs aligned with the laboratory\'s objectives and priorities. This involves creating strategies, setting goals, and establishing timelines for research initiatives. <br/>\r\n\r\nFunding and Grants: Identifying funding opportunities, preparing grant proposals, and securing financial support for research projects. This department often collaborates with funding agencies, both public and private, to acquire resources necessary for research endeavors.<br/>\r\n\r\nCoordination and Collaboration: Facilitating collaboration among researchers, departments, and external partners. This involves organizing interdisciplinary research teams, fostering partnerships with other institutions, and promoting cooperation to address complex scientific challenges.<br/>\r\n\r\nRegulatory Compliance: Ensuring adherence to ethical standards, regulatory guidelines, and legal requirements in research activities. This includes managing protocols for human subjects, animal welfare, biosafety, and research integrity.<br/>\r\n\r\nProject Management: Overseeing the execution of research projects by providing administrative support, monitoring progress, managing budgets, and allocating resources efficiently.<br/>\r\n\r\nData Management and Analysis: Supporting researchers in data collection, analysis, and interpretation. This may involve providing access to specialized tools, databases, or expertise for statistical analysis and data management.<br/>\r\n\r\nReporting and Evaluation: Compiling reports, assessing outcomes, and evaluating the impact of research programs. This includes measuring success against predefined metrics and communicating findings to stakeholders, including funding agencies, leadership, and the scientific community.<br/>\r\n\r\nStrategic Planning: Contributing to the long-term strategic planning of the laboratory by identifying emerging research areas, assessing trends, and recommending directions for future research initiatives.<br/>', 'This department is in charge of all of our research programmes.', 'research.jpg', 2, 1, 1, 4, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(4, 'Pedagogy', '\r\nPedagogy refers to the theory and practice of education, focusing on how teaching and learning occur. The roles of pedagogy are diverse and encompass various aspects that influence and facilitate effective education:', 'This is our department in charge of providing continue training to our personnel to keep them updated in their different fields.', 'pedagogy.jpg', 1, 1, 1, 5, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(5, 'Communication', 'The Communication Department in a laboratory serves a critical function in conveying scientific discoveries, research outcomes, and the institution\'s achievements to various stakeholders.', 'Our e-presence and publications in any kind are managed by this department.', 'communication.jpg', 1, 1, 1, 6, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(6, 'Advisory Committee', 'An advisory committee is a group of individuals assembled to provide guidance, expertise, and advice on specific matters to an organization, institution, or entity. In the context of a laboratory or research institution, an advisory committee serves several crucial roles', NULL, 'advisory_committee.jpg', 1, 0, 0, 7, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(7, 'Executive Direction', 'The role of Executive Direction within an organization, including a laboratory, encompasses several key responsibilities that focus on leadership, strategic management, and operational oversight. ', NULL, 'executive_direction.jpg', 1, 0, 0, 1, '2023-12-26 09:42:26', '2023-12-26 09:42:26');

