	(11, 'IVCC', '', 'Combatting Insect Borne Diseases', 'ivcc.png', NULL, NULL, 1, 1, 'funding_partner', '2023-12-26 12:10:58', '2023-12-26 12:10:58'),
	(12, 'MITSUI', 'MITSUI Chemicals', '', 'MITSUI.png', NULL, NULL, 1, 1, 'industry_partner', '2023-12-26 12:10:58', '2023-12-26 12:10:58'),
	(13, 'New Nets', '', '', 'new_nets_logo.png', NULL, NULL, 1, 1, 'industry_partner', '2023-12-26 12:10:58', '2023-12-26 12:10:58'),
	(14, 'PAM', '', '', 'pam.png', NULL, NULL, 1, 1, 'industry_partner', '2023-12-26 12:10:58', '2023-12-26 12:10:58'),
	(15, 'LSHTM', 'London School of Hygiene and Tropical Medicine', 'The London School of Hygiene & Tropical Medicine is a world leading centre for research and postgraduate education in public and global health. LSHTM has been in collaboration with Centre de Recherche Entomologique de Cotonou (CREC) since over 12 years in research on vector control tools.', 'lshtm.png', NULL, NULL, 1, 1, 'funding_partner', '2023-12-26 12:10:58', '2023-12-26 12:10:58'),
	(16, 'IVCC', '', 'Innovative Vector Control Consortium', 'ivcc.svg', 'https://www.ivcc.com/', 'https://www.linkedin.com/company/ivcc-innovative-vector-control-/posts/?feedView=all', 1, 1, 'funding_partner', NULL, NULL),
	(17, 'CREC', 'Centre de Recherche Entomologique de Cotonou)', 'CREC was established in 1993 and is the leading centre for vector control research in Benin. CREC advices the Ministry of Health of Benin on Malaria Vector Control, performs research and consultancy on Vector Control related issues.', 'crec_logo.png', 'https://crec.bj/', NULL, 1, 1, 'Work partner', NULL, NULL),
	(18, 'PAMVERC-BENIN', 'Pan-African Malaria Vector Research Consortium - BENIN', 'Pan-African Malaria Vector Research Consortium was founded in 2008 as a consortium of three African vector control research sites (including Cotonou, Benin) specializing in the development and evaluation of malaria vector control products and interventions.', 'PAMVERC-LOGO.png', 'https://www.crec-lshtm.org/index.php/about/description_pamverc', 'https://www.linkedin.com/company/pamverc/posts/?feedView=all', 1, 1, 'Work partner', NULL, NULL),
	(19, 'SANAS', NULL, NULL, 'sanas4.png', 'https://www.sanas.co.za/Pages/index.aspx', 'https://www.linkedin.com/company/south-african-national-accreditation-system-sanas-/', 1, 1, 'industry_partner', NULL, NULL),
	(20, 'SUMITOMO', NULL, NULL, 'SUMITO.png', 'https://www.sumitomo-chem.co.jp/english/', 'https://www.linkedin.com/company/sumitomo-chemical/', 1, 1, 'industry_partner', NULL, NULL),
	(21, 'VESTERGAARD', NULL, NULL, 'vestergaard_logo.jpeg', 'https://vestergaardcompany.com/', 'https://www.linkedin.com/company/vestergaard/', 1, 1, 'industry_partner', NULL, NULL),
	(22, 'GAVI', 'GAVI, The Caccine Alliance', NULL, 'gavi_logo.jpeg', 'https://www.gavi.org/fr', 'https://www.linkedin.com/company/gavi/', 1, 1, 'industry_partner', NULL, NULL),
	(23, 'EVI', 'European Vaccine Initiative', NULL, 'evi.jpeg', 'https://www.euvaccine.eu/', 'https://www.linkedin.com/company/european-vaccine-initiative/posts/?feedView=all', 1, 1, 'industry_partner', NULL, NULL),
