  `type_staff` enum('coordination','staff','terrain','stagiaire') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'staff',
  `email_personnel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_professionnel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intro_personnel` text COLLATE utf8mb4_unicode_ci,
  `titre` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `facebook_personnel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `twitter_personnel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `youtube_personnel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `linkedin_personnel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `departement_id` int DEFAULT NULL,
  `poste_id` int DEFAULT NULL,
  `photo_personnel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `niveau_poste` int DEFAULT NULL,
