-- Listage des données de la table projet_airid_africa_db.airid_personnels : ~8 rows (environ)
INSERT INTO `airid_personnels` (`id`, `nom_personnel`, `prenom_personnel`, `sexe`, `type_staff`, `email_personnel`, `email_professionnel`, `intro_personnel`, `titre`, `facebook_personnel`, `twitter_personnel`, `youtube_personnel`, `linkedin_personnel`, `departement_id`, `poste_id`, `photo_personnel`, `niveau_poste`, `poids_personnel`, `created_at`, `updated_at`) VALUES
	(1, 'NGUFOR', 'Corine', 'F', 'coordination', 'corine.ngufor@lshtm.uk.ac', 'corine.ngufor@lshtm.uk.ac', 'Corine Ngufor is Associate Professor of medical entomology at LSHTM with several years of field experience in mosquito biology and vector control. She holds a Masters in the Biology and Control of Disease Vectors and a PhD in medical entomology both from LSHTM.  Her PhD focused on the use of insecticide combinations to improve the control and management of insecticide resistant African malaria vectors. Corine started working at LSHTM in 2011 supervising and coordinating several WHO Phase I and II vector control studies across sub-saharan Africa (Tanzania, Cote D\'Ivoire, Burkina Faso and Benin). She is currently based in Benin since 2013 where she is lead scientist and manager of the GLP-certified CREC/LSHTM Collaborative Research Programme (www.crec-lshtm.org) implementing a large portfolio of vector control projects investigating new vector control tools for targeting insecticide resistant malaria vectors in WHO laboratory, semi-field and randomised controlled trials. Corine is a member of the Vector Control Advisory Group of the World Health Organisation, co-chair of the Vector Control Working Group of the Roll Back Malaria partnership and chair of PAMCA Benin Chapter.', 'Dr.', NULL, NULL, NULL, NULL, 7, 12, 'DrCorine.jpg', 1, 1, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(2, 'GOVOETCHAN', 'Renaud', 'M', 'coordination', 'rgovoetchan@lshtm.uk.ac', 'rgovoetchan@lshtm.uk.ac', 'Renaud is a Medical Entomologist with more than 10 years of experience of conducting malaria vector control studies in communities. He held technical and advisory positions with the US PMI VectorLink Project in Burundi and UNDP/Global Fund in Djibouti prior to joining LSHTM in 2018. In his current role, he coordinates implementation of IVCC-Sponsored WHO/PQ Phase I, II and III studies and RCTs evaluating the efficacy of novel vector control products (mainly long-lasting insecticidal net and indoor residual spraying) at CREC/LSHTM Collaborative Research Programme in Cotonou, Benin.', 'Dr.', NULL, NULL, NULL, NULL, 3, 5, 'Renaud.jpg', 2, 1, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(3, 'AHANHANZO-GLELE', 'Imelda', 'F', 'coordination', 'imelda@crec-lshtm.org', 'imelda@crec-lshtm.org', 'Sed ut perspiciatis unde omnis iste natus error sit voluptatem accusantium doloremque laudantium, totam rem aperiam, eaque ipsa quae ab illo inventore veritatis et quasi architecto beatae vitae dicta sunt explicabo. Nemo enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit, sed quia consequuntur magni dolores eos qui ratione voluptatem sequi nesciunt. Neque porro quisquam est, qui dolorem ipsum quia dolor sit amet, consectetur, adipisci velit, sed quia non numquam eius modi tempora incidunt ut labore et dolore magnam aliquam quaerat voluptatem. Ut enim ad minima veniam, quis nostrum exercitationem ullam corporis suscipit laboriosam, nisi ut aliquid ex ea commodi consequatur? Quis autem vel eum iure reprehenderit qui in ea voluptate velit esse quam nihil molestiae consequatur, vel illum qui dolorem eum fugiat quo voluptas nulla pariatur.', 'Mrs.', NULL, NULL, NULL, NULL, 2, 7, 'Imelda.jpg', 3, 1, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
