-- Listage de la structure de la table projet_airid_africa_db. airid_projects
CREATE TABLE IF NOT EXISTS `airid_projects` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `short_title_project` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `long_title_project` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resume` text COLLATE utf8mb4_unicode_ci,
  `description_sans_html` text COLLATE utf8mb4_unicode_ci,
  `description_riche` text COLLATE utf8mb4_unicode_ci,
  `photo_couverture` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seconde_photo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator_id` int NOT NULL,
  `date_debut_project` date DEFAULT NULL,
  `date_fin_project` date DEFAULT NULL,
  `study_director` int DEFAULT NULL,
  `project_manager` int DEFAULT NULL,
  `sponsor_id` int DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `etat_projet` enum('ongoing','ended','abandoned') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ongoing',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `airid_projects_creator_id_index` (`creator_id`),
  KEY `airid_projects_study_director_index` (`study_director`),
  KEY `airid_projects_project_manager_index` (`project_manager`),
  KEY `airid_projects_sponsor_id_index` (`sponsor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Listage des données de la table projet_airid_africa_db.airid_projects : ~6 rows (environ)
INSERT INTO `airid_projects` (`id`, `short_title_project`, `long_title_project`, `resume`, `description_sans_html`, `description_riche`, `photo_couverture`, `seconde_photo`, `creator_id`, `date_debut_project`, `date_fin_project`, `study_director`, `project_manager`, `sponsor_id`, `category_id`, `etat_projet`, `created_at`, `updated_at`) VALUES
	(2, 'PAMVERC-BENIN', 'PAMVERC-BENIN', 'To maximize capacity to fight malaria and other vector borne diseases, it is important to increase the speed with which vector control products are developed. This includes the timely generation of efficacy data used for product registration.\n                To this intent, PAMVERC-BENIN aims to deliver timely results by reducing administrative processes involved in product testing while maintaining a standard of high quality.\n                PAMVERC-BENIN has developed a strong experience in product testing by testing more than 16 products for up to 7 leading commercial companies over the 3 last years.\n                Phase 1 and Phase 2 evaluations can be tested following the principles of OECD Good Laboratory Principles (GLP) depending on the needs of the client.', 'To maximize capacity to fight malaria and other vector borne diseases, it is important to increase the speed with which vector control products are developed. This includes the timely generation of efficacy data used for product registration.\n                To this intent, PAMVERC-BENIN aims to deliver timely results by reducing administrative processes involved in product testing while maintaining a standard of high quality.\n                PAMVERC-BENIN has developed a strong experience in product testing by testing more than 16 products for up to 7 leading commercial companies over the 3 last years.\n                Phase 1 and Phase 2 evaluations can be tested following the principles of OECD Good Laboratory Principles (GLP) depending on the needs of the client.', 'To maximize capacity to fight malaria and other vector borne diseases, it is important to increase the speed with which vector control products are developed. This includes the timely generation of efficacy data used for product registration.\n                To this intent, PAMVERC-BENIN aims to deliver timely results by reducing administrative processes involved in product testing while maintaining a standard of high quality.\n                PAMVERC-BENIN has developed a strong experience in product testing by testing more than 16 products for up to 7 leading commercial companies over the 3 last years.\n                Phase 1 and Phase 2 evaluations can be tested following the principles of OECD Good Laboratory Principles (GLP) depending on the needs of the client.', 'pamverc.jpg', 'new_irs.jpg', 1, '2020-12-28', NULL, 1, 2, 1, 1, 'ongoing', '2023-12-27 15:57:32', '2023-12-27 15:57:32'),
	(3, 'New Nets project', 'New Nets project', 'The massive scale-up of Long-Lasting Insecticidal Nets (LLIN) has led to a major reduction in malaria burden (up to 50%) in many sub-Saharan African (SSA) countries. However, this progress is threatened by the wide-scale selection of insecticide-resistant malaria vectors.', 'The massive scale-up of Long-Lasting Insecticidal Nets (LLIN) has led to a major reduction in malaria burden (up to 50%) in many sub-Saharan African (SSA) countries. However, this progress is threatened by the wide-scale selection of insecticide-resistant malaria vectors.\n                The “New Nets” study is a cluster-randomised clinical trial which is currently conducting in the districts of Cove, Zagnanado and Ouinhi, located in the Zou department Benin, West Africa. The first output of this research is to evaluate the efficacy of 2 novel dual active Ingredient (AI) LLINs in a community randomized controlled trial on epidemiology outcomes. The trial will take place over 2 years in an area where malaria vectors are resistant to pyrethroid insecticide.\n                Three-arm superiority, a single-blinded, cluster-randomized trial with the village as the unit of randomisation. The primary outcome of the trial will be incidence of malaria cases (confirmed by rapid diagnostic test (RDT)) in children aged 6 months to 10 years followed for 24 months. Secondary outcomes are cross-sectional community prevalence of malaria infection (confirmed by RDT) in the study population at 12- and 24-months post-intervention, the prevalence of moderate and severe anaemia in children under 5 years old, entomological inoculation rates (EIR), vector density and insecticide resistance intensity.\n                The second output has two objectives. The first objective aim to examine whether Phase II experimental hut trial outcomes can serve as a surrogate for epidemiological and transmission outcomes of CRT. The second objective is to assess the LLIN durability in phase III WHOPES/PQ study.', 'The massive scale-up of Long-Lasting Insecticidal Nets (LLIN) has led to a major reduction in malaria burden (up to 50%) in many sub-Saharan African (SSA) countries. However, this progress is threatened by the wide-scale selection of insecticide-resistant malaria vectors.\n                The “New Nets” study is a cluster-randomised clinical trial which is currently conducting in the districts of Cove, Zagnanado and Ouinhi, located in the Zou department Benin, West Africa. The first output of this research is to evaluate the efficacy of 2 novel dual active Ingredient (AI) LLINs in a community randomized controlled trial on epidemiology outcomes. The trial will take place over 2 years in an area where malaria vectors are resistant to pyrethroid insecticide.\n                Three-arm superiority, a single-blinded, cluster-randomized trial with the village as the unit of randomisation. The primary outcome of the trial will be incidence of malaria cases (confirmed by rapid diagnostic test (RDT)) in children aged 6 months to 10 years followed for 24 months. Secondary outcomes are cross-sectional community prevalence of malaria infection (confirmed by RDT) in the study population at 12- and 24-months post-intervention, the prevalence of moderate and severe anaemia in children under 5 years old, entomological inoculation rates (EIR), vector density and insecticide resistance intensity.\n                The second output has two objectives. The first objective aim to examine whether Phase II experimental hut trial outcomes can serve as a surrogate for epidemiological and transmission outcomes of CRT. The second objective is to assess the LLIN durability in phase III WHOPES/PQ study..', 'new_net.jpg', 'pamverc.jpg', 2, '2021-12-28', NULL, 2, 5, 2, 2, 'ongoing', '2023-12-27 15:57:32', '2023-12-27 15:57:32'),
	(4, 'New IRS Project', 'New IRS Project', 'WHO recommends the rotation of insecticides for IRS for managing insecticide resistance in malaria vectors. New IRS insecticides with novel modes of actions to which vectors are largely susceptible are needed for improved control of resistant vector populations and for effective IRS rotations for insecticide resistance management. One of such newly developed insecticides for vector control demonstrated potential to control pyrethroid resistant malaria vectors in laboratory and semi-field experimental hut studies.', 'WHO recommends the rotation of insecticides for IRS for managing insecticide resistance in malaria vectors. New IRS insecticides with novel modes of actions to which vectors are largely susceptible are needed for improved control of resistant vector populations and for effective IRS rotations for insecticide resistance management. One of such newly developed insecticides for vector control demonstrated potential to control pyrethroid resistant malaria vectors in laboratory and semi-field experimental hut studies.\n                CREC/LSHTM will be evaluating this new IRS product evaluation in a community trial in Southern Benin in term of its efficacy and residual activity against pyrethroid resistant malaria vectors in comparison to Fludora® Fusion. The evaluation includes i) assessment of the impact of community IRS application on vector density, vector longevity, vector infectivity and Entomological Innoculation Rate (EIR); ii) assessment of the residual activity of the new IRS product applied for IRS on home walls and iii) assessment of its operational feasibility and community acceptance in Benin.\n                The trial started in 2020 and will run till 2022. The IRS products will be applied in about 9000 households organised in 16 clusters. CREC/LSHTM will work in collaboration with major local/national partners such as CREC, NMCP, Vectorlink and the University of Abomey Calavi.', 'WHO recommends the rotation of insecticides for IRS for managing insecticide resistance in malaria vectors. New IRS insecticides with novel modes of actions to which vectors are largely susceptible are needed for improved control of resistant vector populations and for effective IRS rotations for insecticide resistance management. One of such newly developed insecticides for vector control demonstrated potential to control pyrethroid resistant malaria vectors in laboratory and semi-field experimental hut studies.\n                CREC/LSHTM will be evaluating this new IRS product evaluation in a community trial in Southern Benin in term of its efficacy and residual activity against pyrethroid resistant malaria vectors in comparison to Fludora® Fusion. The evaluation includes i) assessment of the impact of community IRS application on vector density, vector longevity, vector infectivity and Entomological Innoculation Rate (EIR); ii) assessment of the residual activity of the new IRS product applied for IRS on home walls and iii) assessment of its operational feasibility and community acceptance in Benin.\n                The trial started in 2020 and will run till 2022. The IRS products will be applied in about 9000 households organised in 16 clusters. CREC/LSHTM will work in collaboration with major local/national partners such as CREC, NMCP, Vectorlink and the University of Abomey Calavi.', 'new_irs.jpg', 'new_net.jpg', 2, '2018-04-13', NULL, 2, 5, 2, 3, 'ongoing', '2023-12-27 15:57:32', '2023-12-27 15:57:32'),
	(5, 'OPTIMVEC', 'OPTIMVEC', 'The OPTIMVEC project is a cutting-edge research initiative designed to address the challenge of residual malaria transmission during the third year after mass distribution of insecticide-treated nets (ITNs). In Benin, the project is led by the Centre de Recherche Entomologique de Cotonou (CREC) in collaboration with the African Institute for Research in Infectious Diseases (AIRID), with modelling support from Imperial College London.', 'The OPTIMVEC project is a cutting-edge research initiative designed to address the challenge of residual malaria transmission during the third year after mass distribution of insecticide-treated nets (ITNs). In Benin, the project is led by the Centre de Recherche Entomologique de Cotonou (CREC) in collaboration with the African Institute for Research in Infectious Diseases (AIRID), with modelling support from Imperial College London.', ' <div class="row">\r\n\r\n                <div class="col-12">\r\n                    <span class="title-section" style="font-size: 1.2em; font-weight: bold">Optimising Complementary\r\n                        Insecticide-Based Strategies for Malaria Vector Control</span>\r\n                </div>\r\n\r\n                <div class="col-12 mt-2">\r\n                    <h5 class="title-section mt-2">Principal Investigator</h5>\r\n                    <p class="text-justify mt-2">\r\n                        Dr Corine Ngufor\r\n                    </p>\r\n                </div>\r\n\r\n                 <div class="col-12">\r\n                    <h5 class="title-section mt-2">Background</h5>\r\n                    <p class="text-justify mt-2">\r\n                        The OPTIMVEC project is a cutting-edge research initiative\r\n                         designed to address the challenge of residual malaria transmission \r\n                         that persists during the third year after mass distribution of insecticide-treated \r\n                         nets (ITNs). As ITNs age and lose efficacy—especially in areas with widespread \r\n                         insecticide resistance—new strategies are urgently needed to maintain protection. \r\n                         The project aims to identify and optimise insecticide-based interventions that \r\n                        can complement ITNs and enhance overall vector control effectiveness.\r\n                    </p>\r\n                </div>\r\n\r\n\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Project Objectives</h5>\r\n\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Assess the synergistic or antagonistic effects of combining insecticides through laboratory bioassays.\r\n                        </li>\r\n                        <li>\r\n                            Evaluate the efficacy of supplementary vector control tools (e.g., spatial repellents, IRS) with aged ITNs.\r\n                        </li>\r\n                        <li>\r\n                           Model the public health impact of various intervention combinations under diverse conditions.\r\n                        </li>\r\n                        <li>\r\n                            Explore the influence of environmental variables and resistance on intervention outcomes.\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Core Activities</h5>\r\n\r\n                    <p class="text-justify mt-2">\r\n                       <strong> Laboratory Research</strong>\r\n                    </p>\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Testing insecticide combinations against both pyrethroid-susceptible and -resistant mosquitoes.\r\n                        </li>\r\n                        <li>\r\n                            Synergist bioassays (e.g., PBO + pyrethroids).\r\n                        </li>\r\n                        <li>\r\n                            Behavioural assays on mosquito responses to spatial repellents and ITNs.\r\n                        </li>\r\n                    </ul>\r\n\r\n\r\n                    <p class="text-justify mt-2">\r\n                       <strong>Experimental Hut Trials</strong>\r\n                    </p>\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Pairing transfluthrin passive emanators with aged ITNs.\r\n                        </li>\r\n                        <li>\r\n                            Trials in huts with different structural designs.\r\n                        </li>\r\n                        <li>\r\n                            Controlled mosquito release studies with resistant and susceptible strains.\r\n                        </li>\r\n                    </ul>\r\n\r\n\r\n                    <p class="text-justify mt-2">\r\n                        <strong>Modelling & Environmental Analysis</strong>\r\n                    </p>\r\n\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Simulations of malaria burden reduction with various intervention mixes.\r\n                        </li>\r\n                        <li>\r\n                            Analysis of temperature, humidity, and housing factors.\r\n                        </li>\r\n                        <li>\r\n                            Identification of optimal tool combinations for specific settings.\r\n                        </li>\r\n\r\n                    </ul>\r\n                </div>\r\n\r\n\r\n                 <div class="col-12">\r\n                    <h5 class="title-section mt-2">AIRID’s Role</h5>\r\n\r\n                   <p class="text-justify mt-2">\r\n                        AIRID plays a central role in implementing experimental hut studies\r\n                         and supporting laboratory evaluations in Benin. Its field infrastructure \r\n                         and expertise are essential to testing innovative strategies \r\n                        that can inform national and global policies.\r\n                    </p>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Partners & Funders</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n\r\n                        <li>\r\n                            Lead Institution: Centre de Recherche Entomologique de Cotonou (CREC)\r\n                        </li>\r\n                        <li>\r\n                            Research Collaborator: African Institute for Research in Infectious Diseases (AIRID)\r\n                        </li>\r\n                        <li>\r\n                            Modelling Consultant: Imperial College London\r\n                        </li>\r\n                        <li>\r\n                            Funder: Bill & Melinda Gates Foundation\r\n                        </li>\r\n\r\n                    </ul>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Funder</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Budget: USD 1,200,352\r\n                        </li>\r\n                        <li>\r\n                            Timeline: January 2025 – December 2027\r\n                        </li>\r\n\r\n                    </ul>\r\n                </div>\r\n\r\n            </div>', 'new_net.jpg', 'pamverc.jpg', 2, '2025-06-19', NULL, 2, 5, 1, 3, 'ongoing', NULL, NULL),
	(6, 'GAVI-SIRI Project', 'GAVI-SIRI Project', 'The European Vaccine Initiative (EVI) is leading efforts to evaluate the feasibility and impact of a seasonal intensification strategy for malaria vaccination in regions with highly seasonal malaria transmission. The study, conducted in Guinea and Benin, will compare this approach to the standard age-based vaccination schedule to determine its feasibility, implementation challenges, cost-effectiveness, and impact on vaccine uptake and malaria burden.', 'The European Vaccine Initiative (EVI) is leading efforts to evaluate the feasibility and impact of a seasonal intensification strategy for malaria vaccination in regions with highly seasonal malaria transmission. The study, conducted in Guinea and Benin, will compare this approach to the standard age-based vaccination schedule to determine its feasibility, implementation challenges, cost-effectiveness, and impact on vaccine uptake and malaria burden.', '    <div class="row">\r\n\r\n                <div class="col-12">\r\n                    <span class="title-section" style="font-size: 1.2em; font-weight: bold">Seasonal Intensification of\r\n                        Malaria Vaccine Delivery in Benin; feasibility, impact, and cost effectiveness</span>\r\n                </div>\r\n                <div class="col-12    mt-3">\r\n                    <div class="row">\r\n                        <div class="col-12  text-center">\r\n                            <img src="{{ asset(\'storage/assets/projects/gavi_siri.jpg\') }}" class="img-thumbnail "\r\n                                style="height: 420px" alt="">\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <p class="text-justify mt-3">\r\n\r\n                    The GAVI-SIRI project is a multi-country operational research initiative\r\n                    evaluating a new strategy to optimize the timing of malaria vaccine delivery\r\n                    in areas with highly seasonal malaria transmission. In Benin, the project is led\r\n                    by the Centre de Recherche Entomologique de Cotonou (CREC) in collaboration with\r\n                    the African Institute for Research in Infectious Diseases (AIRID) and the\r\n                    national\r\n                    immunisation and malaria control programmes. AIRID plays a central\r\n                    role in coordinating implementation of field research activities.\r\n                </p>\r\n\r\n                <p class="text-justify mt-2">\r\n                    The project aims to determine the feasibility, impact, and cost-effectiveness\r\n                    of intensifying malaria vaccine delivery ahead of the rainy season\r\n                    to enhance protection in young children.\r\n                </p>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Principal Investigator</h5>\r\n                    <p class="text-justify mt-2">\r\n                        Dr Corine Ngufor\r\n                    </p>\r\n                </div>\r\n\r\n                \r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Context</h5>\r\n\r\n\r\n                    <p class="text-justify mt-2">\r\n                        In regions like central Benin, where malaria cases spike during the rainy season,\r\n                        there may be substantial benefit to aligning vaccine delivery with this high-risk\r\n                        period. The project compares a “seasonal intensification” strategy in the\r\n                        Dassa-Glazoué\r\n                        health zone to standard age-based vaccination in Tchaourou. Vaccination efforts are\r\n                        intensified\r\n                        in May and June, and the timing of the fourth vaccine dose is adjusted to ensure\r\n                        maximum protection\r\n                        during peak transmission months.\r\n                    </p>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Key Objectives</h5>\r\n\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Improve malaria vaccine uptake and scheduling among children under 2\r\n                        </li>\r\n                        <li>\r\n                            Enhance protection during peak malaria season\r\n                        </li>\r\n                        <li>\r\n                            Assess feasibility, community acceptance, and operational\r\n                            challenges\r\n                        </li>\r\n                        <li>\r\n                            Determine the cost-effectiveness of seasonal delivery compared to routine\r\n                            age-based vaccination\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Evaluation Components</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Qualitative research with caregivers, health workers, and community leaders\r\n                        </li>\r\n                        <li>\r\n                            Health facility data collection to assess malaria incidence\r\n                        </li>\r\n                        <li>\r\n                            Coverage surveys to measure uptake and timing of vaccine doses\r\n                        </li>\r\n                        <li>\r\n                            Cost analysis and modelling to assess financial sustainability and health\r\n                            impact\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Project Partners</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Ministry of Health (Benin)\r\n                        </li>\r\n                        <li>\r\n                            Centre de Recherche Entomologique de Cotonou (CREC)\r\n                        </li>\r\n                        <li>\r\n                            African Institute for Research in Infectious Diseases (AIRID)\r\n                        </li>\r\n                        <li>\r\n                            London School of Hygiene & Tropical Medicine (LSHTM)\r\n                        </li>\r\n                        <li>\r\n                            European Vaccine Initiative (EVI)\r\n                        </li>\r\n                        <li>\r\n                            WHO/TDR\r\n                        </li>\r\n                        <li>\r\n                            Université de Thiès (Senegal)\r\n                        </li>\r\n                        <li>\r\n                            Université Gamal Abdel Nasser (Guinea)\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Funders</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Gavi, the Vaccine Alliance\r\n                        </li>\r\n                        <li>\r\n                            Global Health EDCTP3\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Budget</h5>\r\n\r\n                    <p class="text-justify mt-2">\r\n                        USD 2,070,791\r\n                    </p>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Timeline</h5>\r\n\r\n                    <p class="text-justify mt-2">\r\n                        The study began in May 2025, with preliminary results expected in early 2026.\r\n                        Outcomes will inform malaria\r\n                        vaccine policy and delivery strategies across sub-Saharan Africa.\r\n                    </p>\r\n                </div>\r\n\r\n\r\n            </div>', 'gavi_siri.jpg', 'gavi2.jpg', 2, '2025-05-26', NULL, 2, 5, 1, 3, 'ongoing', NULL, NULL),
	(7, 'ATSB Project', 'ATSB Project', 'The project aims to address critical knowledge gaps concerning the sugar-feeding behaviors of African malaria vectors and how these behaviors may affect the effectiveness of Attractive Targeted Sugar Baits (ATSBs). The research will be structured around three distinct work packages.', 'The project aims to address critical knowledge gaps concerning the sugar-feeding behaviors of African malaria vectors and how these behaviors may affect the effectiveness of Attractive Targeted Sugar Baits (ATSBs). The research will be structured around three distinct work packages.', '     <div class="row">', 'atsb.jpg', 'atsb2.jpg', 2, NULL, NULL, 2, 5, 1, 3, 'ongoing', NULL, NULL),
	(8, 'DuraNet® Plus Multi-Country Durability Study', 'DuraNet® Plus Multi-Country Durability Study', 'The DuraNet® Plus Durability Study is a major multi-country operational research project evaluating the long-term physical and insecticidal durability of DuraNet® Plus—a WHO-prequalified long-lasting insecticidal net (LLIN) that combines alpha-cypermethrin and piperonyl butoxide (PBO) to improve protection against pyrethroid-resistant malaria vectors.', 'The DuraNet® Plus Durability Study is a major multi-country operational research project evaluating the long-term physical and insecticidal durability of DuraNet® Plus—a WHO-prequalified long-lasting insecticidal net (LLIN) that combines alpha-cypermethrin and piperonyl butoxide (PBO) to improve protection against pyrethroid-resistant malaria vectors.', '  <div class="row">\r\n\r\n                <div class="col-12">\r\n                    <span class="title-section" style="font-size: 1.2em; font-weight: bold">Evaluating the longevity and\r\n                        efficacy of next-generation mosquito nets</span>\r\n                </div>\r\n               \r\n\r\n                <p class="text-justify mt-3">\r\n\r\n                    The DuraNet® Plus Durability Study is a major multi-country\r\n                    operational research project evaluating the long-term physical\r\n                    and insecticidal durability of DuraNet® Plus—a WHO-prequalified\r\n                    long-lasting insecticidal net (LLIN) that combines alpha-cypermethrin\r\n                        and piperonyl butoxide (PBO) to improve protection against pyrethroid-resistant malaria\r\n                    vectors.\r\n                </p>\r\n\r\n                <p class="text-justify mt-2">\r\n                    The study is conducted across Benin, Cameroon, and Tanzania,\r\n                    representing diverse malaria transmission settings in West, Central,\r\n                    and East Africa. It compares the performance of DuraNet® Plus to a standard\r\n                    pyrethroid-only LLIN (DuraNet®) over a three-year period of household use.\r\n                </p>\r\n\r\n                 <div class="col-12">\r\n                    <h5 class="title-section mt-2">Principal Investigator</h5>\r\n                    <p class="text-justify mt-2">\r\n                        Dr Corine Ngufor\r\n                    </p>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Role of AIRID</h5>\r\n\r\n\r\n                    <p class="text-justify mt-2">\r\n                        AIRID is a core partner in this multi-country study, contributing\r\n                        to field implementation, entomological evaluations, and cross-site\r\n                            coordination. The experimental hut trials in Benin—used to assess bioefficacy\r\n                        under natural conditions—are conducted at AIRID’s Semi-Field Station in Covè.\r\n                    </p>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Lead Partner</h5>\r\n\r\n\r\n                    <p class="text-justify mt-2">\r\n                         PAMVERC-BENIN (Pan-African Malaria Vector Research Consortium)\r\n                        serves as the lead partner, coordinating study design, data quality assurance,\r\n                        and overall project implementation across countries.\r\n                    </p>\r\n                </div>\r\n\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Study Objectives</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Assess net attrition, fabric integrity, insecticidal content, and bioefficacy\r\n                            over time\r\n                        </li>\r\n                        <li>\r\n                            Compare the durability and effectiveness of DuraNet® Plus to conventional pyrethroid-only LLINs\r\n                        </li>\r\n                        <li>\r\n                            Monitor  PBO performance against resistant mosquito populations\r\n                        </li>\r\n                        <li>\r\n                            Provide high-quality evidence to guide procurement\r\n                                and policy decisions at national and global levels\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Evaluation Components</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                             Household surveys to monitor net usage, wear-and-tear, and user acceptability\r\n                        </li>\r\n                        <li>\r\n                            Chemical analysis and bioassays to assess active ingredient\r\n                            content and mosquito knockdown\r\n                        </li>\r\n                        <li>\r\n                            Experimental hut trials  with free-flying resistant mosquitoes\r\n                        </li>\r\n                        <li>\r\n                            Qualitative research on user perception and behaviour\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                 <div class="col-12">\r\n                    <h5 class="title-section mt-2">Study Locations</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Benin – Zakpota District\r\n                        </li>\r\n                        <li>\r\n                            Cameroon – Mbalmayo District\r\n                        </li>\r\n                        <li>\r\n                            Tanzania – Muheza District\r\n                        </li>\r\n                    </ul>\r\n\r\n                    <p class="text-justify mt-2">\r\n                        Each country includes approximately 1,800 households, with two follow-up cohorts \r\n                        (non-destructive and destructive sampling) monitored over 36 months.\r\n                    </p>\r\n                </div>\r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Project Partners</h5>\r\n\r\n                    <ul class="text-justify mt-2">\r\n                        <li>\r\n                            Pan-African Malaria Vector Research Consortium PAMVERC-BENIN (Lead)\r\n                        </li>\r\n                        <li>\r\n                            African Institute for Research in Infectious Diseases (AIRID)\r\n                        </li>\r\n                        <li>\r\n                            Centre de Recherche Entomologique de Cotonou (CREC), Benin\r\n                        </li>\r\n                        <li>\r\n                           Centre for Research in Infectious Diseases (CRID), Cameroon\r\n                        </li>\r\n                        <li>\r\n                            National Institute for Medical Research (NIMR), Tanzania\r\n                        </li>\r\n                        <li>\r\n                           Shobikaa Impex Pvt. Ltd. (Product manufacturer and funder)\r\n                        </li>\r\n                      \r\n                    </ul>\r\n                </div>\r\n\r\n               \r\n\r\n                <div class="col-12">\r\n                    <h5 class="title-section mt-2">Timeline</h5>\r\n\r\n                    <p class="text-justify mt-2">\r\n                        2023–2025 – Ongoing follow-up and data collection <br>\r\n                        Final results expected by late 2025\r\n\r\n                    </p>\r\n                </div>\r\n\r\n\r\n            </div>', 'new_net.jpg', 'pamverc.jpg', 2, '2025-06-19', NULL, 2, 5, 1, 3, 'ongoing', NULL, NULL),
	(9, 'VESTERGAARD ITN Testing', 'VESTERGAARD ITN Testing', '', '', ' <div class="row">\n\n                <div class="col-12">\n                    <span class="title-section" style="font-size: 1.2em; font-weight: bold">Supporting Innovation in Vector\n                        Control: R&D Collaboration with PAMVERC-BENIN and Vestergaard Sarl</span>\n                </div>\n\n\n\n                <div class="col-12 mt-2">\n                    <p class="text-justify mt-2">\n                        AIRID, through its involvement in the Pan-African Malaria Vector Research\n                        Consortium (PAMVERC), plays a key role in supporting the research and\n                        development (R&D) of next-generation insecticide-treated nets (ITNs)\n                        developed by Vestergaard Sarl—a global leader in disease prevention technologies.\n                    </p>\n                </div>\n\n\n                <div class="col-12">\n                    <h5 class="title-section mt-2">What We Do</h5>\n\n                    <p class="text-justify mt-2">\n                        As part of this collaboration, AIRID conducts rigorous evaluations of\n                        Vestergaard’s ITN products across three major research platforms:\n                    </p>\n\n                    <ul class="text-justify mt-2">\n                        <li>\n                            Laboratory Bioassays: Controlled tests to assess the bioefficacy of Vestergaard’s\n                            innovative insecticide formulations against local strains of malaria vectors, including\n                            resistant populations.\n                        </li>\n                        <li>\n                            Experimental Hut Trials: Semi-field studies in purpose-built huts\n                            to measure mosquito mortality, blood-feeding inhibition,\n                            and deterrence in realistic exposure scenarios.\n                        </li>\n                        <li>\n                            Community-Level Field Studies: Longitudinal evaluations of net durability, bioefficacy, and\n                            community\n                            acceptance under real-world conditions, in line with WHO guidelines.\n                        </li>\n\n                    </ul>\n                </div>\n\n                <div class="col-12">\n                    <h5 class="title-section mt-2">Our Impact</h5>\n\n                    <p class="text-justify mt-2">\n                        By generating high-quality data on the performance and\n                        longevity of Vestergaard ITNs, AIRID helps accelerate the\n                        development, optimization, and regulatory approval\n                        of tools that strengthen malaria control and resistance management strategies across Africa.\n                    </p>\n                </div>\n\n\n                <div class="col-12">\n                    <h5 class="title-section mt-2">Collaborative Science for African Health</h5>\n\n                    <p class="text-justify mt-2">\n                        This partnership reinforces AIRID’s commitment\n                        to science-led innovation, evidence-based public health,\n                        and African leadership in global health R&D. Through PAMVERC\n                        and other regional networks, AIRID is advancing a shared vision for\n                        sustainable malaria control driven by African institutions and local expertise.\n                    </p>\n                </div>\n\n\n            </div>', 'pamverc.jpg', 'new_irs.jpg', 1, '2020-12-28', NULL, 1, 2, 1, 1, 'ongoing', '2023-12-27 15:57:32', '2023-12-27 15:57:32');

