-- Listage des données de la table projet_airid_africa_db.airid_publications : ~38 rows (environ)
INSERT INTO `airid_publications` (`id`, `titre_publication`, `resume_publication`, `url_publication`, `numero_doi`, `numero_pmid`, `numero_pmcid`, `keywords`, `fichier_publication`, `date_publication`, `annee_publication`, `auteurs`, `photo_couverture`, `created_at`, `updated_at`) VALUES
	(39, 'Community evaluation of the physical and insecticidal durability of DuraNet® Plus, an alpha-cypermethrin and piperonyl butoxide incorporated mosquito net: protocol for a multi-country study in West, Central and East Africa', 'Pyrethroid-PBO nets have demonstrated improved impact against clinical malaria transmitted by pyrethroid resistant mosquito vectors and are being scaled up across Africa. However very little is known about their physical and insecticidal durability under operational conditions. This study will investigate the attrition, fabric integrity, insecticide content and bioefficacy of DuraNet® Plus, a new WHO prequalified alphacypermethrin and PBO incorporated net developed by Shobikaa Impex Private Limited over 3 years of field use in communities in Benin, Cameroon and Tanzania.', 'https://archpublichealth.biomedcentral.com/articles/10.1186/s13690-023-01217-w', '', NULL, NULL, NULL, 's13690-023-01217-w.pdf', '', 2023, 'Abel Agbevo, Idelphonse Ahogni, Benjamin Menze, Patrick Tungu, Elison E. Kemibala, Renaud Govoetchan, Charles Wondji, Germain Gil Padonou & Corine Ngufor', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(40, 'Community evaluation of VECTRON™ T500, a brofanilide insecticide, for indoor residual spraying for malaria vector control in central Benin; a two arm nonâinferiority cluster randomised', 'VECTRON™ T500 is a wettable powder IRS formulation of broflanilide, a newly discovered insecticide. We performed a two-arm non-inferiority community randomised evaluation of VECTRON™ T500, compared to Fludora® Fusion against pyrethroid-resistant Anopheles gambiae s.l. in an area of high coverage with pyrethroid-only nets in the Za-Kpota District of central Benin. One round of IRS was applied in all consenting households in the study area. Sixteen clusters were randomised (1:1) to receive VECTRON™ T500 (100 mg/m2 for broflanilide) or Fludora® Fusion (200 mg/m2 for clothianidin and 25 mg/m2 for deltamethrin). Surveys were performed to assess adverse events and the operational feasibility and acceptability of VECTRON™ T500 among spray operators and household inhabitants. Human landing catches were conducted in 6 households every 1–2 months for up to 18 months post-intervention to assess the impact on vector densities, sporozoite rates and entomological inoculation rates. Bottle bioassays were performed to monitor vector susceptibility to pyrethroids, broflanilide and clothianidin. Monthly wall cone bioassays were conducted for 24 months to assess the residual efficacy of the IRS formulations using susceptible and pyrethroid-resistant An. gambiae s.l. A total of 26,562 female mosquitoes were collected during the study, of which 40% were An. gambiae s.l., the main malaria vector in the study area. The vector population showed high intensity pyrethroid resistance but was susceptible to broflanilide (6 µg/bottle) and clothianidin (90 µg/bottle). Using a non-inferiority margin of 50%, vector density indicated by the human biting rate (bites/person/night) was non-inferior in the VECTRON™ T500 arm compared to the Fludora® Fusion arm both indoors (0.846 bites/p/n in Fludora® Fusion arm vs. 0.741 bites/p/n in VECTRON™ T500 arm, IRR 0.54, 95% CI 0.22–1.35, p = 0.150) and outdoors (0.691 bites/p/n in Fludora® Fusion arm vs. 0.590 bites/p/n in VECTRON™ T500 clusters, IRR 0.75, 95% CI 0.41–1.38, p = 0.297). Sporozoite rates and entomological inoculation rates did not differ significantly between study arms (sporozoite rate: 0.9% vs 1.1%, p = 0. 0.746, EIR: 0.008 vs 0.006 infective bites per person per night, p = 0.589). Cone bioassay mortality with both VECTRON™ T500 and Fludora® Fusion was 100% for 24 months post-IRS application on both cement and mud treated house walls with both susceptible and pyrethroid-resistant strains of An. gambiae s.l. Perceived adverse events reported by spray operators and householders were generally very low (< 6%) in both study arms. VECTRON™ T500 was non-inferior to Fludora® Fusion in reducing the risk of malaria transmission by pyrethroid resistant vectors when applied for IRS in communities in central Benin. The insecticide showed prolonged residual efficacy on house walls, lasting over 24 months and had a high acceptability with homeowners. Community application of VECTRON™ T500 for IRS provides improved and prolonged control of pyrethroid resistant malaria vectors and enhances our capacity to manage insecticide resistance.', 'https://www.nature.com/articles/s41598-023-45047-w', '', NULL, NULL, NULL, 's41598-023-45047-w.pdf', '', 2023, 'Corine Ngufor, Renaud Govoetchan, Augustin Fongnikin, Corneille Hueha, Juniace Ahoga, Thomas Syme, Abel Agbevo, Abdoulaye Daleb, Graham Small, Derric Nimmo, John Bradley, Rock Aikpon, Laurent Iyikirenga, Razaki Osse, Filemon Tokponnon & Germain Gil Padonou', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(41, 'Evaluating the attrition, fabric integrity and insecticidal durability of two dual active ingredient nets (Interceptor® G2 and Royal® Guard): methodology for a prospective study embedded in a cluster randomized controlled trial in Benin', 'Following the World Health Organization (WHO) endorsement of dual active ingredient (AI) nets, an increased uptake of pyrethroid-chlorfenapyr and pyrethroid-pyriproxyfen nets is expected. Studies evaluating their physical and insecticidal durability are essential for making programmatic and procurement decisions. This paper describes the methodology for a prospective study to evaluate the attrition, fabric integrity, insecticidal durability of Interceptor® G2 (alpha-cypermethrin-chlorfenapyr) and Royal Guard® (alpha-cypermethrin-pyriproxyfen), compared to Interceptor® (alpha-cypermethrin), embedded in a 3-arm cluster randomized controlled trial (cRCT) in the Zou Department of Benin.', 'https://malariajournal.biomedcentral.com/articles/10.1186/s12936-023-04708-x', '', NULL, NULL, NULL, 's12936-023-04708-x.pdf', '', 2023, 'Corine Ngufor, Augustin Fongnikin, Josias Fagbohoun, Abel Agbevo, Thomas Syme, Juniace Ahoga, Manfred Accrombessi, Natacha Protopopoff, Jackie Cook, Thomas S. Churcher, Germain Gil Padonou, Renaud Govoetchan & Martin Akogbeto', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(42, 'Investigating discriminating concentrations for monitoring susceptibility to broflanilide and cross resistance to other insecticide classes in Anopheles gambiae sensu lato, using the new WHO bottle bioassay method.', 'Broflanilide is a new insecticide being developed for malaria vector control. As new insecticide chemistries become available, strategies to preserve the susceptibility of local malaria vectors and extend their useful life need to be considered before large scale deployment. This requires the development of appropriate testing procedures and identification of suitable discriminating concentrations for monitoring susceptibility in wild vector populations to facilitate decision making by control programmes.', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0276246', '', NULL, NULL, NULL, 'journal.pone.0276246.pdf', '', 2023, 'Renaud Govoetchan, Abibath Odjo,Damien Todjinou,Graham Small, Augustin Fongnikin, Corine Ngufor', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(43, 'PermaNet® Dual, a new deltamethrin-chlorfenapyr mixture net, shows improved efficacy against pyrethroid-resistant Anopheles gambiae sensu lato in southern Benin | bioRxiv..', 'Pyrethroid-chlorfenapyr nets have demonstrated improved entomological and epidemiological impact in trials across Africa. This is driving increased demand for this novel net class in malaria endemic countries. PermaNet® Dual is a new deltamethrin-chlorfenapyr net developed by Vestergaard Sàrl to provide more options to malaria control programmes. We performed an experimental hut trial to evaluate the efficacy of PermaNet® Dual against wild, free-flying pyrethroid-resistant Anopheles gambiae sensu lato in Covè, Benin. PermaNet® Dual induced superior levels of mosquito mortality compared to a pyrethroid-only net and a pyrethroid-piperonyl butoxide net both when unwashed (77% with PermaNet® Dual vs. 23% with PermaNet® 2.0 and 56% with PermaNet® 3.0, p<0.001) and after 20 standardised washes (75% with PermaNet® Dual vs. 14% with PermaNet® 2.0 and 30% with PermaNet® 3.0, p<0.001). Using a provisional non-inferiority margin defined by the World Health Organisation, PermaNet® Dual was also non-inferior to a pyrethroid-chlorfenapyr net that has demonstrated improved public health value (Interceptor® G2), for vector mortality (79% vs. 76%, OR=0.854, 95% CIs: 0.703–1.038) but not for blood-feeding protection (35% vs. 26%, OR=1.445, 95% CIs: 1.203–1.735). PermaNet® Dual presents an additional option of this highly effective net class for improved control of malaria transmitted by pyrethroid-resistant mosquitoes.', 'https://www.biorxiv.org/content/10.1101/2023.02.02.526745v1', '', NULL, NULL, NULL, '2023.02.02.526745v1.full.pdf', '', 2023, 'Thomas Syme, Boris N’dombidjé, Martial Gbegbo, Damien Todjinou, Victoria Ariori, Patricia De Vos, Olivier Pigeon, Corine Ngufor', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(44, 'Efficacy of pyriproxyfen-pyrethroid long-lasting insecticidal nets (LLINs) and chlorfenapyr-pyrethroid LLINs compared with pyrethroid-only LLINs for malaria control in Benin: a cluster-randomised, superiority trial.', 'New classes of long-lasting insecticidal nets (LLINs) combining mixtures of insecticides with different modes of action could put malaria control back on track after rebounds in transmission across sub-Saharan Africa. We evaluated the relative efficacy of pyriproxyfen-pyrethroid LLINs and chlorfenapyr-pyrethroid LLINs compared with standard LLINs against malaria transmission in an area of high pyrethroid resistance in Benin..', 'https://www.thelancet.com/journals/lancet/article/PIIS0140-6736(22)02319-4/fulltext', '', NULL, NULL, NULL, 'PIIS0140673622023194.pdf', '', 2023, 'Manfred Accrombessi*, Jackie Cook*, Edouard Dangbenon, Boulais Yovogan, Hilaire Akpovi, Arthur Sovi, Constantin Adoha, Landry Assongba, Aboubacar Sidick, Bruno Akinro, Razaki Ossè, Filémon Tokponnon, Rock Aïkpon, Aurore Ogouyemi-Hounto, Germain Gil Padonou, Immo Kleinschmidt, Louisa A Messenger, Mark Rowland, Corine Ngufor, Natacha Protopopoff†, Martin C Akogbeto†', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(45, 'VECTRON™ T500, a new broflanilide insecticide for indoor residual spraying, provides prolonged control of pyrethroid-resistant malaria vectors.', 'Broflanilide is a newly discovered insecticide with a novel mode of action targeting insect γ-aminobutyric acid receptors. The efficacy of VECTRON™ T500, a wettable powder formulation of broflanilide, was assessed for IRS against wild pyrethroid-resistant malaria vectors in experimental huts in Benin.', 'https://malariajournal.biomedcentral.com/articles/10.1186/s12936-022-04336-x', '', NULL, NULL, NULL, 's12936-022-04336-x.pdf', '', 2022, 'Renaud Govoetchan, Augustin Fongnikin, Thomas Syme, Graham Small, Martial Gbegbo, Damien Todjinou, Mark Rowland, Derric Nimmo, Germain Gil Padonou & Corine Ngufor', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(46, 'Inferring the epidemiological benefit of indoor vector control interventions against malaria from mosquito data..', 'The cause of malaria transmission has been known for over a century but it is still unclear whether entomological measures are sufficiently reliable to inform policy decisions in human health. Decision-making on the effectiveness of new insecticide-treated nets (ITNs) and the indoor residual spraying of insecticide (IRS) have been based on epidemiological data, typically collected in cluster-randomised control trials. The number of these trials that can be conducted is limited. Here we use a systematic review to highlight that efficacy estimates of the same intervention may vary substantially between trials. Analyses indicate that mosquito data collected in experimental hut trials can be used to parameterize mechanistic models for Plasmodium falciparum malaria and reliably predict the epidemiological efficacy of quick-acting, neuro-acting ITNs and IRS. Results suggest that for certain types of ITNs and IRS using this framework instead of clinical endpoints could support policy and expedite the widespread use of novel technologies..', 'https://pubmed.ncbi.nlm.nih.gov/35790746/', 'https://www.doi.org/10.1038/s41467-022-30700-1', 'https://pubmed.ncbi.nlm.nih.gov/35790746', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9256631', NULL, 's41467-022-30700-1.pdf', '', 2022, 'Ellie Sherrard-Smith, Corine Ngufor, Antoine Sanou, Moussa W Guelbeogo, Raphael N\'Guessan, Eldo Elobolobo, Francisco Saute, Kenyssony Varela, Carlos J Chaccour, Rose Zulliger, Joseph Wagman, Molly L Robertson, Mark Rowland, Martin J Donnelly, Samuel Gonahasa, Sarah G Staedke, Jan Kolaczinski, Thomas S Churcher', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(47, 'Strain Characterisation for Measuring Bioefficacy of ITNs Treated with Two Active Ingredients (Dual-AI ITNs): Developing a Robust Protocol by Building Consensus...', 'Durability monitoring of insecticide-treated nets (ITNs) containing a pyrethroid in combination with a second active ingredient (AI) must be adapted so that the insecticidal bioefficacy of each AI can be monitored independently. An effective way to do this is to measure rapid knock down of a pyrethroid-susceptible strain of mosquitoes to assess the bioefficacy of the pyrethroid component and to use a pyrethroid-resistant strain to measure the bioefficacy of the second ingredient. To allow robust comparison of results across tests within and between test facilities, and over time, protocols for bioefficacy testing must include either characterisation of the resistant strain, standardisation of the mosquitoes used for bioassays, or a combination of the two. Through a series of virtual meetings, key stakeholders and practitioners explored different approaches to achieving these goals. Via an iterative process we decided on the preferred approach and produced a protocol consisting of characterising mosquitoes used for bioefficacy testing before and after a round of bioassays, for example at each time point in a durability monitoring study. We present the final protocol and justify our approach to establishing a standard methodology for durability monitoring of ITNs containing pyrethroid and a second AI.', 'https://pubmed.ncbi.nlm.nih.gov/35621770/', 'https://www.doi.org/10.3390/insects13050434', 'https://pubmed.ncbi.nlm.nih.gov/35621770', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9144861', ' bioefficacy; dual active ingredients (dual-AI); durability monitoring; insecticide resistance; insecticide-treated nets (ITN); method development; mosquito; product evaluation; pyrethroid; quality control (QC); strain characterisation;insecticide-treated nets (ITN); pyrethroid; mosquito; strain characterisation; insecticide resistance; method development; durability monitoring; product evaluation; quality control (QC); dual active ingredients (dual-AI); bioefficacy', 'insects-13-00434-v2.pdf', '', 2022, 'Rosemary S Lees, Jennifer S Armistead, Salum Azizi, Edi Constant, Christen Fornadel, John E Gimnig, Janet Hemingway, Daniel Impoinvil, Seth R Irish, William Kisinza, Natalie Lissenden, Henry D Mawejje, Louisa A Messenger, Sarah Moore, Corine Ngufor, Richard Oxborough, Natacha Protopopoff, Hilary Ranson, Graham Small, Joseph Wagman, David Weetman, Sarah Zohdy, Angus Spiers', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(48, 'Pirikool® 300 CS, a new long-lasting capsule suspension formulation of the organophosphate insecticide pirimiphos-methyl for indoor residual spraying against pyrethroid-resistant malaria vectors.', 'Indoor residual spraying (IRS) using a capsule suspension formulation of the organophosphate insecticide, pirimiphos-methyl, has provided substantial malaria control in many communities in Africa. However, only one brand of this product has been recommended by the World Health Organisation for IRS. To help increase the diversity of the portfolio of IRS insecticides and offer suitable options to procurers and malaria vector control programmes, additional product brands of this highly effective and long-lasting insecticide formulation for IRS will be needed.', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0267229', 'https://doi.org/10.1371/journal.pone.0267229', '', '', '', 'journal.pone.0267229.pdf', '', 2022, 'Fongnikin A, Odjo A, Akpi J, Kiki L, Ngufor C.', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(49, 'Pyrethroid-piperonyl butoxide (PBO) nets reduce the efficacy of indoor residual spraying with pirimiphos-methyl against pyrethroid-resistant malaria vectors.', 'Pirimiphos-methyl is a pro-insecticide requiring activation by mosquito cytochrome P450 enzymes to induce toxicity while PBO blocks activation of these enzymes in pyrethroid-resistant vector mosquitoes. PBO may thus antagonise the toxicity of pirimiphos-methyl IRS when combined with pyrethroid-PBO ITNs. The impact of combining Olyset Plus and PermaNet 3.0 with Actellic 300CS IRS was evaluated against pyrethroid-resistant Anopheles gambiae s.l. in two parallel experimental hut trials in southern Benin. The vector population was resistant to pyrethroids and PBO pre-exposure partially restored deltamethrin toxicity but not permethrin. Mosquito mortality in experimental huts was significantly improved in the combinations of bendiocarb IRS with pyrethroid-PBO ITNs (33-38%) compared to bendiocarb IRS alone (14-16%, p < 0.001), demonstrating an additive effect. Conversely, mortality was significantly reduced in the combinations of pirimiphos-methyl IRS with pyrethroid-PBO ITNs (55-59%) compared to pirimiphos-methyl IRS alone (77-78%, p < 0.001), demonstrating evidence of an antagonistic effect when both interventions are applied in the same household. Mosquito mortality in the combination was significantly higher compared to the pyrethroid-PBO ITNs alone (55-59% vs. 22-26% p < 0.001) showing potential of pirimiphos-methyl IRS to enhance vector control when deployed to complement pyrethroid-PBO ITNs in an area where PBO fails to fully restore susceptibility to pyrethroids..', 'https://pubmed.ncbi.nlm.nih.gov/35478216/', 'https://www.doi.org/10.1038/s41598-022-10953-y', 'https://pubmed.ncbi.nlm.nih.gov/35478216', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9046380 ', '', 's41598-022-10953-y.pdf', '', 2022, 'Syme T, Gbegbo M, Obuobi D, Fongnikin A, Agbevo A, Todjinou D & Ngufor C.', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(50, 'The Automatic Classification of Pyriproxyfen-Affected Mosquito Ovaries.', 'Pyriproxyfen (PPF) may become an alternative insecticide for areas where pyrethroid-resistant vectors are prevalent. The efficacy of PPF can be assessed through the dissection and assessment of vector ovaries. However, this reliance on expertise is subject to limitations. We show here that these limitations can be overcome using a convolutional neural network (CNN) to automate the classification of egg development and thus fertility status. Using TensorFlow, a resnet-50 CNN was pretrained with the ImageNet dataset. This CNN architecture was then retrained using a novel dataset of 524 dissected ovary images from An. gambiae s.l. An. gambiae Akron, and An. funestus s.l., whose fertility status and PPF exposure were known. Data augmentation increased the training set to 6973 images. A test set of 157 images was used to measure accuracy. This CNN model achieved an accuracy score of 94%, and application took a mean time of 38.5 s. Such a CNN can achieve an acceptable level of precision in a quick, robust format and can be distributed in a practical, accessible, and free manner. Furthermore, this approach is useful for measuring the efficacy and durability of PPF treated bednets, and it is applicable to any PPF-treated tool or similarly acting insecticide...', 'https://www.researchgate.net/publication/357177751_The_Automatic_Classification_of_Pyriproxyfen-Affected_Mosquito_Ovaries', 'https://www.doi.org/10.3390/insects12121134', '', '  ', '', 'The_Automatic_Classification_of_Pyriproxyfen-Affec.pdf', '', 2021, 'Mark T. Fowler , Rosemary S. Lees , Josias Fagbohoun , Nancy S. Matowo , Corine Ngufor ,Natacha Protopopoff and Angus Spiers  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(51, 'Can pyrethroid-piperonyl butoxide (PBO) nets reduce the efficacy of indoor residual spraying with pirimiphos-methyl against pyrethroid-resistant malaria vectors?', 'As the uptake of pyrethroid-PBO ITNs increases, their combination with IRS insecticides could become an operational reality in many malaria-endemic communities. Pirimiphos-methyl is a pro-insecticide requiring activation by mosquito cytochrome P450 enzymes to induce toxicity while PBO blocks activation of these enzymes in pyrethroid-resistant vector mosquitoes. PBO may thus antagonise the toxicity of pirimiphos-methyl IRS when combined with pyrethroid-PBO ITNs. The impact of combining two major brands of pyrethroid-PBO ITNs (Olyset Plus, PermaNet 3.0) with pirimiphos-methyl IRS (Actellic 300CS) was evaluated against pyrethroid-resistant Anopheles gambiae sl in two parallel experimental hut trials in southern Benin in comparison to bendiocarb IRS and each intervention alone. The wild vector population was resistant to pyrethroids but susceptible to pirimiphos-methyl and bendiocarb. PBO pre-exposure partially restored deltamethrin toxicity but not permethrin. Mosquito mortality in experimental huts was significantly improved in the combinations of bendiocarb IRS with Olyset Plus (33%) and PermaNet 3.0 (38%) compared to bendiocarb IRS alone (14 to 16%, p<0.001), demonstrating an additive effect. Conversely, mortality was significantly reduced in the combinations of pirimiphos-methyl IRS with Olyset Plus (59%) and PermaNet 3.0 (55%) compared to pirimiphos-methyl IRS alone (77 to 78%, p<0.001), demonstrating an antagonistic effect. Combining pirimiphos-methyl IRS with the pyrethroid-PBO ITNs provided significantly improved mosquito mortality (55 to 5​9​%​)​...', 'https://www.researchgate.net/publication/356929107_Can_pyrethroid-piperonyl_butoxide_PBO_nets_reduce_the_efficacy_of_indoor_residual_spraying_with_pirimiphos-methyl_against_pyrethroid-resistant_malaria_vectors', 'https://www.doi.org/10.1101/2021.12.08.471747', '', '  ', '', 'Can_pyrethroid-piperonyl_butoxide_PBO_nets_reduce_.pdf', '', 2021, 'Thomas Syme, Martial Gbegbo, Dorothy Obuobi, Augustin Fongnikin, Abel Agbevo, Damien Todjinou, Corine Ngufor  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(52, 'Systematic review of the entomological impact of insecticide-treated nets evaluated using experimental hut trials in Africa', 'Resistance of anopheline mosquitoes to pyrethroid insecticides is spreading rapidly across sub-Saharan Africa, diminishing the efficacy of insecticide-treated nets (ITNs) – the primary tool for preventing malaria. The entomological efficacy of indoor vector control interventions can be measured in experimental hut trials (EHTs), where hut structures resemble local housing, but allow the collection of mosquitoes that entered, exited, blood-fed and/or died. There is a need to understand how the spread of resistance changes ITN efficacy and to elucidate factors influencing EHT results, including differences in experimental hut design, to support the development of novel vector control tools. A comprehensive database of EHTs was compiled following a systematic review to identify all known trials investigating ITNs or indoor residual spraying across sub-Saharan Africa. This analysis focuses on EHTs investigating ITNs and uses Bayesian statistical models to characterise the complex interaction between ITNs and mosquitoes, the between-study variability, and the impact of pyrethroid resistance. As resistance rises, the entomological efficacy of ITNs declines. They induce less mortality and are less likely to deter mosquitoes from entering huts. Despite this, ITNs continue to offer considerable personal protection by reducing mosquito feeding until resistance reaches high levels. There are clear associations between the different entomological impacts of ITNs, though there is still substantial variability between studies, some of which can be accounted for by hut design....', 'https://www.researchgate.net/publication/353975683_Systematic_review_of_the_entomological_impact_of_insecticide-treated_nets_evaluated_using_experimental_hut_trials_in_Africa', '', '', '  ', '', '1-s2.0-S2667114X21000418-main.pdf', '', 2021, 'Rebecca K. Nash, Ben Lambert, Raphael N’Guessan, Corine Ngufor, Mark Rowland, Richard Oxborough, Sarah Moore, Patrick Tungu, Ellie Sherrard-Smith, Thomas S.Churcher  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(53, 'Pre-intervention characteristics of themosquito species in Benin in preparation for arandomized controlled trial assessing theefficacy of dual active-ingredient long-lastinginsecticidal nets for controlling insecticide-resistant malaria vectors', 'This study provides detailed characteristics of vector populations in preparation for a three arm cluster randomized controlled trial (RCT) aiming to compare the community impact of dual active-ingredient (AI) long-lasting insecticidal nets (LLINs) that combine two novel insecticide classes–chlorfenapyr or pyriproxifen–with alpha-cypermethrin to improve the prevention of malaria transmitted by insecticide-resistant vectors compared to standard pyrethroid LLINs. Methods The study was carried out in 60 villages across Cove, Zangnanando and Ouinhi districts, southern Benin. Mosquito collections were performed using human landing catches (HLCs). After morphological identification, a sub-sample of Anopheles gambiae s.l. were dissected for parity, analyzed by PCR for species and presence of L1014F kdr mutation and by ELISA-CSP to identify Plasmodium falciparum sporozoite infection. WHO susceptibility tube tests were performed by exposing adult An. gambiae s.l., collected as larvae from each district, to 0.05% alphacypermethrin, 0.75% permethrin, 0.1% bendiocarb and 0.25% pirimiphos-methyl. Synergist assays were also conducted with exposure first to 4% PBO followed by alpha-cypermethrin. Results An. gambiae s.l. (n = 10807) was the main malaria vector complex found followed by Anopheles funestus s.l. (n = 397) and Anopheles nili (n = 82). An. gambiae s.l. was comprised of An. coluzzii (53.9%) and An. gambiae s.s. (46.1%), both displaying a frequency of the L1014F kdr mutation >80%. Although more than 80% of people slept under standard LLIN, human biting rate (HBR) i​n', 'https://www.researchgate.net/publication/353975683_Systematic_review_of_the_entomological_impact_of_insecticide-treated_nets_evaluated_using_experimental_hut_trials_in_Africa', '', '', '  ', '', 'Yovoganetal.2020.pdf', '', 2021, 'Boulais Yovogan, Arthur SoviID, Gil G. Padonou, Constantin J. Adoha, Bruno Akinro, Saïd Chitou, Manfred Accrombessi, Edouard Dangbe, Hilaire Akpovi, Louisa A. Messenger, Razaki Ossè, Aurore Ogouyemi Hounto,Jackie Cook, Immo Kleinschmidt, Corine Ngufor, Mark Rowland, Natacha Protopopoff, Martin C. Akogbeto  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(54, 'Efficacy of broflanilide (VECTRON T500), a new meta-diamide insecticide, for indoor residual spraying against pyrethroid-resistant malaria vectors', 'The rotational use of insecticides with different modes of action for indoor residual spraying (IRS) is recommended for improving malaria vector control and managing insecticide resistance. Insecticides with new chemistries are urgently needed. Broflanilide is a newly discovered insecticide under consideration. We investigated the efficacy of a wettable powder (WP) formulation of broflanilide (VECTRON T500) for IRS on mud and cement wall substrates in laboratory and experimental hut studies against pyrethroid-resistant malaria vectors in Benin, in comparison with pirimiphos-methyl CS (Actellic 300CS). There was no evidence of cross-resistance to pyrethroids and broflanilide in CDC bottle bioassays. In laboratory cone bioassays, broflanilide WP-treated substrates killed > 80% of susceptible and pyrethroid-resistant An. gambiae sl for 6–14 months. At application rates of 100 mg/m ² and 150 mg/m ² , mortality of wild pyrethroid-resistant An. gambiae sl entering experimental huts in Covè, Benin treated with VECTRON T500 was similar to pirimiphos-methyl CS (57–66% vs. 56%, P > 0.05). Throughout the 6-month hut trial, monthly wall cone bioassay mortality on VECTRON T500 treated hut walls remained > 80%. IRS with broflanilide shows potential to significantly improve the control of malaria transmitted by pyrethroid-resistant mosquito vectors and could thus be a crucial addition to the current portfolio of IRS insecticides.', 'https://www.researchgate.net/publication/350824552_Efficacy_of_broflanilide_VECTRON_T500_a_new_meta-diamide_insecticide_for_indoor_residual_spraying_against_pyrethroid-resistant_malaria_vectors', 'https://www.doi.org/10.1038/s41598-021-86935-3', '', '  ', '', 'Efficacy_of_broflanilide_VECTRON_T500_a_new_meta-d.pdf', '', 2021, 'Corine Ngufor, Renaud Govoetchan, Augustin Fongnikin, Estelle Vigninou, Thomas Syme, Martin Akogbeto & Mark Rowland  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(55, 'Systematic review of the entomological impact of insecticide-treated nets evaluated using experimental hut trials in Africa', 'Resistance of anopheline mosquitoes to pyrethroid insecticides is spreading rapidly across sub-Saharan Africa, diminishing the efficacy of insecticide-treated nets (ITNs) - the primary tool for preventing malaria. The entomological efficacy of indoor vector control interventions can be measured in experimental hut trials (EHTs), which are specially designed to quantify the protection provided under controlled conditions. Experimental hut structures resemble local housing but allow collection of surviving exiting mosquitoes as well as dead or dying mosquitoes. There is a need to understand how the spread of resistance changes ITN efficacy and to elucidate factors influencing EHT results, including differences in experimental hut construction and design features, to support the development of novel vector control tools. Methods: A comprehensive database of EHTs was compiled and summarised following a systematic review to identify all known trials investigating ITNs or indoor residual spraying (IRS) across sub-Saharan Africa. This analysis focuses on EHTs investigating ITNs and uses Bayesian statistical models to characterise the complex interaction between ITNs and mosquitoes, the variability between studies, and the impact of pyrethroid resistance. Results: As resistance rises, the entomological efficacy of ITNs declines. They induce less mortality and are less likely to deter mosquitoes from entering huts. Despite this, ITNs continue to offer considerable personal protection by reducing mosquito feeding until resistance reaches high levels..', 'https://www.researchgate.net/publication/350824552_Efficacy_of_broflanilide_VECTRON_T500_a_new_meta-diamide_insecticide_for_indoor_residual_spraying_against_pyrethroid-resistant_malaria_vectors', 'https://www.doi.org/10.1101/2021.04.07.21254306', '', '  ', '', 'Systematic_review_of_the_entomological_impact_of_i.pdf', '', 2021, 'Rebecca K Nash, Ben Lambert, Raphael N’Guessan, Corine Ngufor, Mark Rowland, Richard Oxborough, Sarah Moore, Patrick Tungu, Ellie Sherrard-Smith, Thomas S Churcher  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(56, 'Assessing the efficacy of two dual-active ingredients long-lasting insecticidal nets for the control of malaria transmitted by pyrethroid-resistant vectors in Benin: study protocol for a three-arm, single-blinded, parallel, cluster-randomized controlled trial', ' Long-lasting insecticidal nets (LLINs) are currently the primary method of malaria control in sub-Saharan Africa and have contributed to a significant reduction in malaria burden over the past 15 years. However, this progress is threatened by the wide-scale selection of insecticide-resistant malaria vectors. It is, therefore, important to accelerate the generation of evidence for new classes of LLINs. Methods This protocol presents a three-arm superiority, single-blinded, cluster randomized controlled trial to evaluate the impact of 2 novel dual-active ingredient LLINs on epidemiological and entomological outcomes in Benin, a malaria-endemic area with highly pyrethroid-resistant vector populations. The study arms consist of (i) Royal Guard® LLIN, a net combining a pyrethroid (alpha-cypermethrin) plus an insect growth regulator (pyriproxyfen), which in the adult female is known to disrupt reproduction and egg fertility; (ii) Interceptor G2® LLIN, a net incorporating two adulticides (alpha-cypermethrin and chlorfenapyr) with different modes of action; and (iii) the control arm, Interceptor® LLIN, a pyrethroid (alpha-cypermethrin) only LLIN. In all arms, one net for every 2 people will be distributed to each household. Sixty clusters were identified and randomised 1:1:1 to each study arm. The primary outcome is malaria case incidence measured over 24 months through active case detection in a cohort of 25 children aged 6 months to 10 years, randomly selected from each cluster. Secondary outcomes include 1) malaria infection prevalence (all ages) and prevalence of moderate to severe a​n​a​e​m​i​a​ ', 'https://www.researchgate.net/publication/350824552_Efficacy_of_broflanilide_VECTRON_T500_a_new_meta-diamide_insecticide_for_indoor_residual_spraying_against_pyrethroid-resistant_malaria_vectors', 'https://www.doi.org/10.1186/s12879-021-05879-1', '', '  ', '', 'Assessing_the_efficacy_of_two_dual-active_ingredie.pdf', '', 2021, 'Manfred Accrombessi, Jackie Cook, Corine Ngufor, Arthur Sovi, Edouard Dangbenon, Boulais Yovogan, Hilaire Akpovi, Aurore Hounto, Charles Thickstun, Gil G. Padonou, Filemon Tokponnon,Louisa A. Messenger,Immo Kleinschmidt,Mark Rowland,Martin C. Akogbeto,Natacha Protopopoff  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(57, 'Which indoor residual spraying insecticide best complements standard pyrethroid long-lasting insecticidal nets for improved control of pyrethroid resistant malaria vectors?', ' Where resources are available, non-pyrethroid IRS can be deployed to complement standard pyrethroid LLINs with the aim of achieving improved vector control and managing insecticide resistance. The impact of the combination may however depend on the type of IRS insecticide deployed. Studies comparing combinations of pyrethroid LLINs with different types of non-pyrethroid IRS products will be necessary for decision making. ', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0245804', 'https://doi.org/10.1371/journal.pone.0245804', '', '  ', '', 'journal.pone.0245804.pdf', '', 2021, 'Thomas Syme, Augustin Fongnikin, Damien Todjinou, Renaud Govoetchan, Martial Gbegbo, Mark Rowland, Martin Akogbeto, Corine Ngufor  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(58, 'Efficacy of broflanilide (VECTRON T500), a new meta-diamide insecticide, for indoor residual spraying against pyrethroid-resistant malaria vectors', ' The rotational use of insecticides with different modes of action for indoor residual spraying (IRS) is recommended for improving malaria vector control and managing insecticide resistance. Insecticides with new chemistries are urgently needed. Broflanilide is a newly discovered insecticide under consideration. We investigated the efficacy of a wettable powder (WP) formulation of broflanilide (VECTRON T500) for IRS on mud and cement wall substrates in laboratory and experimental hut studies against pyrethroid-resistant malaria vectors in Benin, in comparison with pirimiphos-methyl CS (Actellic 300CS). There was no evidence of cross-resistance to pyrethroids and broflanilide in CDC bottle bioassays. In laboratory cone bioassays, broflanilide WP-treated substrates killed > 80% of susceptible and pyrethroid-resistant An. gambiae sl for 6–14 months. At application rates of 100 mg/m2 and 150 mg/m2, mortality of wild pyrethroid-resistant An. gambiae sl entering experimental huts in Covè, Benin treated with VECTRON T500 was similar to pirimiphos-methyl CS (57–66% vs. 56%, P > 0.05). Throughout the 6-month hut trial, monthly wall cone bioassay mortality on VECTRON T500 treated hut walls remained > 80%. IRS with broflanilide shows potential to significantly improve the control of malaria transmitted by pyrethroid-resistant mosquito vectors and could thus be a crucial addition to the current portfolio of IRS insecticides.. ', 'https://www.nature.com/articles/s41598-021-86935-3', '', '', '  ', '', 's41598-021-86935-3 (1).pdf', '', 2021, 'Corine Ngufor, Renaud Govoetchan, Augustin Fongnikin, Estelle Vigninou, Thomas Syme, Martin Akogbeto & Mark Rowland  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(59, 'Efficacy of broflanilide (VECTRON™ T500), a new meta-diamide insecticide, for indoor residual spraying against pyrethroid-resistant malaria vectors', ' The rotational use of insecticides with different modes of action for indoor residual spraying (IRS) is recommended for improving malaria vector control and managing insecticide resistance. Insecticides with new chemistries are urgently needed. Broflanilide is a newly discovered insecticide under consideration. We investigated the efficacy of a wettable powder (WP) formulation of broflanilide (VECTRON T500) for IRS on mud and cement wall substrates in laboratory and experimental hut studies against pyrethroid-resistant malaria vectors in Benin, in comparison with pirimiphos-methyl CS (Actellic 300CS). There was no evidence of cross-resistance to pyrethroids and broflanilide in CDC bottle bioassays. In laboratory cone bioassays, broflanilide WP-treated substrates killed > 80% of susceptible and pyrethroid-resistant An. gambiae sl for 6–14 months. At application rates of 100 mg/m2 and 150 mg/m2, mortality of wild pyrethroid-resistant An. gambiae sl entering experimental huts in Covè, Benin treated with VECTRON T500 was similar to pirimiphos-methyl CS (57–66% vs. 56%, P > 0.05). Throughout the 6-month hut trial, monthly wall cone bioassay mortality on VECTRON T500 treated hut walls remained > 80%. IRS with broflanilide shows potential to significantly improve the control of malaria transmitted by pyrethroid-resistant mosquito vectors and could thus be a crucial addition to the current portfolio of IRS insecticides.. ', 'https://www.biorxiv.org/content/10.1101/2020.11.06.367961v1', 'https://doi.org/10.1101/2020.11.06.367961', '', '  ', '', '2020.11.06.367961v1.full.pdf', '', 2020, 'Corine Ngufor, Renaud Govoetchan, Augustin Fongnikin, Estelle Vigninou, Thomas Syme, Martin Akogbeto, Mark Rowland  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(60, 'Efficacy of Fludora® Fusion (a mixture of deltamethrin and clothianidin) for indoor residual spraying against pyrethroid-resistant malaria vectors: laboratory and experimental hut evaluation', ' A new generation of IRS insecticides which can provide improved and prolonged control of pyrethroid-resistant malaria vector populations are being developed. Fludora® Fusion is a new IRS insecticide containing a mixture of deltamethrin and clothianidin, a neonicotinoid... ', 'https://parasitesandvectors.biomedcentral.com/articles/10.1186/s13071-020-04341-6', '', '', '  ', '', 's13071-020-04341-6.pdf', '', 2020, 'Augustin Fongnikin, Nadia Houeto, Abel Agbevo, Abibath Odjo, Thomas Syme, Raphael N’Guessan & Corine Ngufor  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(61, 'Indoor spraying with chlorfenapyr (a pyrrole insecticide) provides residual control of pyrethroid-resistant malaria vectors in southern Benin', 'New classes of insecticides with novel modes of action, which can provide effective and prolonged control of insecticide-resistant malaria vector populations, are urgently needed for indoor residual spraying. Such insecticides can be included in a rotation plan to manage and prevent further development of resistance in mosquito vectors of malaria. Chlorfenapyr, a novel pyrrole insecticide with a unique mode of action, is being developed as a long-lasting IRS formulation.... ', 'https://malariajournal.biomedcentral.com/articles/10.1186/s12936-020-03325-2', '', '', '  ', '', 's12936-020-03325-2.pdf', '', 2020, 'Corine Ngufor, Augustin Fongnikin, Neil Hobbs, Martial Gbegbo, Laurette Kiki, Abibath Odjo, Martin Akogbeto & Mark Rowland;  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(62, 'Efficacy of Royal Guard, a new alpha-cypermethrin and pyriproxyfen treated mosquito net, against pyrethroidâÂÂÂÂÂÂresistant malaria vectors', 'Royal Guard is a new insecticide-treated bed-net incorporated with a mixture of alpha-cypermethrin and pyriproxyfen (an insect growth regulator). We assessed its efficacy and wash-resistance in laboratory and experimental hut studies following WHO guidelines. Mosquitoes that survived exposure to the net were kept in separate oviposition chambers and observed for the reproductive effects of pyriproxyfen. In laboratory assays, Royal Guard induced > 80% mortality and > 90% blood-feeding inhibition of An. gambiae sl mosquitoes before and after 20 standardised washes and sterilised blood-fed mosquitoes which remained alive after exposure to the net. In an experimental hut trial against wild free-flying pyrethroid-resistant An. gambiae sl in Cové Benin, Royal Guard through the pyrethroid component induced comparable levels of mortality and blood-feeding inhibition to a standard pyrethroid-only treated net before and after 20 washes and sterilised large proportions of surviving blood-fed female mosquitoes through the pyriproxyfen component; Royal Guard induced 83% reduction in oviposition and 95% reduction in offspring before washing and 25% reduction in oviposition and 50% reduction in offspring after 20 washes. Royal Guard has the potential to improve malaria vector control and provide better community protection against clinical malaria in pyrethroid-resistant areas compared to standard pyrethroid-only LLINs. ', 'https://www.nature.com/articles/s41598-020-69109-5', '', '', '  ', '', 's41598-020-69109-5.pdf', '', 2020, 'Corine Ngufor, Abel Agbevo, Josias Fagbohoun, Augustin Fongnikin & Mark Rowland ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(63, '	\n                Indoor residual spraying with a mixture of clothianidin (a neonicotinoid insecticide) and deltamethrin provides improved control and long residual activity against pyrethroid resistant Anopheles gambiae sl in Southern Benin. PLoS ONE 12(12): e0189575.', 'There is an urgent need for new insecticides for indoor residual spraying (IRS) which can provide improved and prolonged control of malaria vectors that have developed resistance to existing insecticides. The neonicotinoid, clothianidin represents a class of chemistry new to public health. Clothianidin acts as an agonist on nicotinic acetyl choline receptors. IRS with a mixture of Clothianidin and another WHO approved insecticide such as deltamethrin could provide improved control of insecticide resistant malaria vector populations and serve as a tool for insecticide resistance management.', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0189575', '', '', '  ', '', 'Indoor_residual_spraying_with_a_mixture.pdf', '', 2017, 'Ngufor C, Fongnikin A, Rowland M, N’Guessan  ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(64, 'Which intervention is better for malaria vector control: insecticide mixture long-lasting insecticidal nets or standard pyrethroid nets combined with indoor residual spraying?', 'Malaria control today is threatened by widespread insecticide resistance in vector populations. The World Health Organization (WHO) recommends the use of a mixture of unrelated insecticides for indoor residual spraying (IRS) and long-lasting insecticidal nets (LNs) or as a combination of interventions for improved vector control and insecticide resistance management. Studies investigating the efficacy of these different strategies are necessary..', 'https://malariajournal.biomedcentral.com/articles/10.1186/s12936-017-1987-5', '', '', '  ', '', 's12936-017-1987-5.pdf', '', 2017, 'Ngufor C, Fagbohoun J, Critchley J, N’Guessan R, Todjinou D, Malone D, Akogbeto M, and Rowland M ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(65, 'Efficacy of the Olyset Duo net against insecticide-resistant mosquito vectors of malaria. Science translational Medicine, 8(356).', 'Olyset Duo is a new long-lasting insecticidal net treated with permethrin (a pyrethroid) and pyriproxyfen, an insect growth regulator that disrupts the maturation of oocytes in mosquitoes exposed to the net. We tested the Olyset Duo net against pyrethroid-resistant Anopheles gambiae mosquitoes, which transmit malaria parasites, in laboratory bioassays and in a trial in Benin using experimental huts that closely resemble local habitations. Host-seeking mosquitoes that entered to feed were free to contact the occupied nets and were collected the next morning from exit traps. Surviving blood-fed mosquitoes were observed for effects on reproduction. Control nets were treated with pyrethroid only or pyriproxyfen only, and nets were tested unwashed and after 20 standardized washes. The Olyset Duo net showed improved efficacy and wash resistance relative to the pyrethroid-treated net in terms of mosquito mortality and prevention of blood feeding. The production of offspring among surviving blood-fed A. gambiae in the hut trial was reduced by the pyriproxyfen-treated net and the Olyset Duo net both before washing (90 and 71% reduction, respectively) and after washing (38 and 43% reduction, respectively). The degree of reproductive suppression in the hut trial was predicted by laboratory tunnel tests but not by cone bioassays. The overall reduction in reproductive rate of A. gambiae with the Olyset Duo net in the trial was 94% with no washing and 78% after 20 washes. The Olyset Duo net has the potential to provide community control of mosquito populations and reduce malaria transmission in areas of high insecticide resistance..', 'https://www.science.org/doi/10.1126/scitranslmed.aad3270', 'https://www.doi.org/10.1126/scitranslmed.aad327', '', '  ', '', '', '', 2016, 'Ngufor C, N’Guessan R, Fagbohoun J, Todjinou D, Odjo A, Malone D, Ismail H, Akogbeto M and Mark Rowland', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(66, 'Chlorphenapyr (A pyrrole insecticide) applied alone or as a mixture with Alpha-cypermethrin for indoor residual spraying against pyrethroid resistant Anopheles gambiae sl: an experimental hut study in cove, Benin. PLoS ONE. 11(9).', 'Indoor spraying of walls and ceilings with residual insecticide remains a primary method of malaria control. Insecticide resistance in malaria vectors is a growing problem. Novel insecticides for indoor residual spraying (IRS) which can improve the control of pyrethroid resistant malaria vectors are urgently needed. Insecticide mixtures have the potential to improve efficacy or even to manage resistance in some situations but this possibility remains underexplored experimentally. Chlorfenapyr is a novel pyrrole insecticide which has shown potential to improve the control of mosquitoes which are resistant to current WHO-approved insecticides..', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0162210', '', '', '  ', '', '2016.pdf', '', 2016, 'Ngufor C, Critchley J, Fagbohoun J, N’Guessan R, Todjinou D and Rowland M', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(67, 'A chlorphenapyr mixture net Interceptor G2 shows high efficacy and wash durability against resistant mosquitoes in West Africa. PLoS ONE 11(11).', 'Malaria control through use of long-lasting insecticidal nets (LN) is threatened by the selection of anopheline mosquitoes strongly resistant to pyrethroid insecticides. To sustain future effectiveness it is essential to identify and evaluate novel insecticides suitable for nets. Mixtures of two insecticides with contrasting mode of action have the potential to kill resistant vectors and restore transmission control provided the formulation can withstand regular washing over the net’s life span.', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0165925', '', '', '  ', '', '', '', 2016, 'N’guessan R, Odjo A, Ngufor C, Malone D and Mark Rowland', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(68, 'Insecticide resistance profile of Anopheles gambiae from a phase II field station in cove, southern Benin: implications for the evaluation of novel vector control product. Malaria journal, 14.464.', 'Novel indoor residual spraying (IRS) and long-lasting insecticidal net (LLIN) products aimed at improving the control of pyrethroid-resistant malaria vectors have to be evaluated in Phase II semi-field experimental studies against highly pyrethroid-resistant mosquitoes. To better understand their performance it is necessary to fully characterize the species composition, resistance status and resistance mechanisms of the vector populations in the experimental hut sites..', 'https://malariajournal.biomedcentral.com/articles/10.1186/s12936-015-0981-z', '', '', '  ', '', 's12936-015-0981-z.pdf', '', 2015, 'Ngufor C, N’Guessan R, Fagbohoun J, Subramaniam K ,Odjo A, Fongnikin A, Akogbeto M, Weetman D and Rowland M', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(69, 'Mosquito nets treated with a mixture of chlorfenapyr and alphacypermethrin control pyrethroid resistant Anopheles gambiae and Culex quinquefasciatus mosquitoes in West Africa.', 'The effectiveness of insecticide treated nets is under threat across Africa south of the Sahara from the selection of pyrethroid resistance in Anopheles gambiae mosquitoes. To maintain progress against malaria it is necessary to identify alternative residual insecticides for mosquito nets. Mixtures of pyrethroid and insecticides with novel mode of action provide scope for both improved control and management of resistance through concurrent exposure to unrelated insecticides..', 'https://pubmed.ncbi.nlm.nih.gov/24498360/', 'https://www.doi.org/10.1371/journal.pone.0087710', 'https://pubmed.ncbi.nlm.nih.gov/24498360', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3912058 ', '', 'file.pdf', '', 2014, 'N’Guessan R, Ngufor C, Kudom A, Boko P, Odjo A, Malone D and Rowland M', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(70, 'Olyset Duo® (a Pyriproxyfen and Permethrin Mixture Net): An Experimental Hut Trial against Pyrethroid Resistant Anopheles gambiae and Culex quinquefasciatus in Southern Benin', 'Alternative compounds which can complement pyrethroids on long-lasting insecticidal nets (LN) in the control of pyrethroid resistant malaria vectors are urgently needed. Pyriproxyfen (PPF), an insect growth regulator, reduces the fecundity and fertility of adult female mosquitoes. LNs containing a mixture of pyriproxyfen and pyrethroid could provide personal protection through the pyrethroid component and reduce vector abundance in the next generation through the sterilizing effect of pyriproxyfen..', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0093603', 'https://www.doi.org/10.1371/journal.pone.0093603', '', '', '', 's12936-015-0981-z.pdf', '', 2014, 'Ngufor C, N’Guessan R, Fagbohoun J, Odjo A, Malone D, Akogbeto M, and Rowland M', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(71, 'A new long-lasting indoor residual formulation of the organophosphate insecticide pirimiphos methyl for prolonged control of pyrethroid-resistant mosquitoes: an experimental hut trial in Benin', 'Alternative compounds which can complement pyrethroids on long-lasting insecticidal nets (LN) in the control of pyrethroid resistant malaria vectors are urgently needed. Pyriproxyfen (PPF), an insect growth regulator, reduces the fecundity and fertility of adult female mosquitoes. LNs containing a mixture of pyriproxyfen and pyrethroid could provide personal protection through the pyrethroid component and reduce vector abundance in the next generation through the sterilizing effect of pyriproxyfen..', 'https://pubmed.ncbi.nlm.nih.gov/23936033/', 'https://www.doi.org/10.1371/journal.pone.0069516', 'https://pubmed.ncbi.nlm.nih.gov/23936033', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3720653', '', 'file_2.pdf', '', 2013, 'Mark Rowland ,Pelagie Boko,Abibatou Odjo,Alex Asidi,Martin Akogbeto,Raphael N’Guessan', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(72, 'Loss of Household Protection from Use of Insecticide-Treated Nets against Pyrethroid-Resistant Mosquitoes, Benin', 'Pyrethroid resistance is becoming widespread in Anopheles gambiae mosquitoes, coinciding with expanded use of insecticide-treated nets (ITNs) throughout Africa. To investigate whether nets in use are still protective, we conducted household trials in northern and southern Benin, where An. gambiae mosquitoes are susceptible and resistant, respectively, to pyrethroids. Rooms were fitted with window traps and monitored for mosquito biting and survival rates before and after the nets were treated with pyrethroid. Sleeping under an ITN in the location with resistant mosquitoes was no more protective than sleeping under an untreated net, regardless of its physical condition. By contrast, sleeping under an ITN in the location with susceptible mosquitoes decreased the odds of biting by 66%. ITNs provide little or no protection once the mosquitoes become resistant and the netting acquires holes. Resistance seriously threatens malaria control strategies based on ITN...', 'https://wwwnc.cdc.gov/eid/article/18/7/12-0218_article', '', '', '', '', '12-0218.pdf', '', 2012, 'Alex Asidi, Raphael N’Guessan, Martin Akogbeto, Chris Curtis1, and Mark Rowland', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(73, 'Combining indoor residual spraying with chlorfenapyr and long-lasting insecticidal bed nets for improved control of pyrethroid-resistant Anopheles gambiae: an experimental hut trial in Benin', 'Neither indoor residual spraying (IRS) nor long-lasting insecticidal nets (LLINs) are able to fully interrupt transmission in holoendemic Africa as single interventions. The combining of IRS and LLINs presents an opportunity for improved control and management of pyrethroid resistance through the simultaneous presentation of unrelated insecticides.', 'https://malariajournal.biomedcentral.com/articles/10.1186/1475-2875-10-343', '', '', '', '', '1475-2875-10-343.pdf', '', 2011, 'Corine Ngufor, Raphael N\'Guessan, Pelagie Boko, Abibatou Odjo, Estelle Vigninou, Alex Asidi, Martin Akogbeto & Mark Rowland', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(74, 'An experimental hut evaluation of PermaNet® 3.0, a deltamethrin–piperonyl butoxide combination net, against pyrethroid-resistant Anopheles gambiae and Culex quinquefasciatus mosquitoes in southern Benin', 'PermaNet 3.0 is a long-lasting combination net with deltamethrin present on the sides and a mixture of deltamethrin and piperonyl butoxide (PBO), an oxidase synergist, on the top panel. An experimental hut trial comparing unwashed and 20 times washed PermaNet 3.0 and PermaNet 2.0, Olyset Net and a conventional deltamethrin-treated net washed three times was conducted in southern Benin. Anopheles gambiae and Culex quinquefasciatus from this area are highly resistant to pyrethroids through kdr and cytochrome P450 mechanisms. The unwashed PermaNet 3.0 killed slightly more A. gambiae (52%) than the unwashed PermaNet 2.0 (44%) (P = 0.036), indicating only partial synergism of resistance. After washing there was significant loss of activity to a similar level, with PermaNet 3.0 killing 31%, PermaNet 2.0 killing 29% and the conventional net killing 26%. Blood-feeding rates were partially inhibited for unwashed PermaNet 3.0 and Olyset Net (27% inhibition). Personal protection against A. gambiae derived from PermaNet 3.0 was similar to that from PermaNet 2.0 before washing (50% vs. 47%), and after 20 washes it decreased to 30%. Against C. quinquefasciatus, no treatment killed >24% entering the huts. The synergism from unwashed PermaNet 3.0 was lower than expected, probably due to an unidentified resistance mechanism unaffected by PBO..', 'https://www.sciencedirect.com/science/article/abs/pii/S0035920310001823', '', '', '', '', '2010.pdf', '', 2010, 'Raphael N’Guessan, Alex Asidi, Pelagie Boko, Abibatou Odjo, Martin Akogbeto, Olivier Pigeon, Mark Rowland', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(75, 'Control of pyrethroid and DDT-resistant Anopheles gambiae by application of indoor residual spraying or mosquito nets treated with a long-lasting organophosphate insecticide, chlorpyrifos-methyl', 'Scaling up of long-lasting insecticidal nets (LLINs) and indoor residual spraying (IRS) with support from the Global Fund and President\'s Malaria Initiative is providing increased opportunities for malaria control in Africa. The most cost-effective and longest-lasting residual insecticide DDT is also the most environmentally persistent. Alternative residual insecticides exist, but are too short-lived or too expensive to sustain. Dow Agrosciences have developed a microencapsulated formulation (CS) of the organophosphate chlorpyrifos methyl as a cost-effective, long-lasting alternative to DDT...', 'https://malariajournal.biomedcentral.com/articles/10.1186/1475-2875-9-44', '', '', '', '', '1475-2875-9-44.pdf', '', 2010, 'Raphael N\'Guessan, Pelagie Boko, Abibathou Odjo, Joseph Chabi, Martin Akogbeto & Mark Rowland ', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01'),
	(76, 'Control of pyrethroid-resistant Anopheles gambiae and Culex quinquefasciatus mosquitoes with chlorfenapyr in Benin', 'To compare the efficacy of chlorfenapyr applied on mosquito nets and as an indoor residual spray against populations of Anopheles gambiae and Culex quinquefasciatus in an area of Benin that shows problematic levels of pyrethroid resistance....', 'https://onlinelibrary.wiley.com/doi/full/10.1111/j.1365-3156.2009.02245.x', 'https://doi.org/10.1111/j.1365-3156.2009.02245.x', '', '', '', 'Tropical_Med_Int_Health_2009_NGuessan_Control_of_pyrethroid_resistant_Anopheles_gambiae_and_Culex_quinquefasciatus.pdf', '', 2010, 'Raphael N’Guessan, Pelagie Boko, Abiba Odjo, Bart Knols, Martin Akogbeto, Mark Rowland', 'publication.jpg', '2023-12-29 10:10:01', '2023-12-29 10:10:01');

