  KEY `airid_sub_departements_chef_sous_departement_index` (`chef_sous_departement`),
  KEY `airid_sub_departements_departement_id_index` (`departement_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Listage des données de la table projet_airid_africa_db.airid_sub_departements : ~16 rows (environ)
INSERT INTO `airid_sub_departements` (`id`, `nom_sous_departement`, `description_sous_departement`, `photo_sous_departement`, `chef_sous_departement`, `departement_id`, `created_at`, `updated_at`) VALUES
	(1, 'Accounts and Finance', 'Accounting and finance departments within a laboratory or any organization are vital for managing financial transactions, maintaining fiscal health, and providing insights crucial for decision-making.', 'finance.jpg', 4, 2, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(2, 'Human Resource Management', 'Human Resource Management (HRM) within a laboratory involves various functions related to managing the workforce, fostering a conducive work environment, and aligning human capital with the organization\'s goals. ', 'human.jpg', 4, 2, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(3, 'Logistics and procurement', 'Logistics and procurement in a laboratory play critical roles in ensuring the efficient management of resources, materials, and supplies essential for research activities. ', 'logistics.jpg', 4, 2, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(4, 'Business administration', 'Business administration in a laboratory context involves managing the administrative and operational aspects to support the scientific research and organizational goals. ', 'business.jpg', 4, 2, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(5, 'Public health entomology (CREC-LSHTM/PAMVERC)', 'Public health entomology is a field of study focused on the relationship between insects and human health, specifically addressing the impact of insects on the transmission of diseases and the development of strategies to control insect-borne illnesses', 'public_health.jpg', 1, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(6, 'Social Sciences', '\r\nSocial sciences encompass a diverse range of disciplines that study human society and social relationships. These disciplines use various methods and theories to understand human behavior, social interactions, and societal structures.', 'social.jpg', 2, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(7, 'Parasitology & Microbiology', 'Parasitology and microbiology are branches of biology that focus on the study of microorganisms', 'parasitology.jpg', 2, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(8, 'Biotechnology', 'iotechnology involves the use of biological systems, organisms, or their derivatives to develop products and applications to benefit humans and the environment. It\'s an interdisciplinary field that merges biology with technology and has wide-ranging applications across various industries', 'biotech.jpg', 2, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(9, 'Virology', 'Virology is the branch of microbiology that focuses on the study of viruses and viral diseases. It encompasses various aspects of viruses, their structure, classification, replication, evolution, and their interactions with hosts. ', 'virology.jpg', 2, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(10, 'Epidemiology & Public Health', 'Epidemiology is the study of the distribution, causes, patterns, and determinants of health and diseases in populations. Epidemiologists use various methods to investigate the factors influencing the occurrence and spread of diseases. ', 'epidemio.jpg', 2, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(11, 'Quality Assurance', 'Quality assurance (QA) refers to the systematic processes, procedures, and activities implemented within an organization to ensure that products, services, or processes meet specified standards of quality and comply with regulatory requirements.', 'qa.jpg', 6, 3, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(12, 'MSc Public Health Entomology', 'An MSc (Master of Science) in Public Health Entomology is a specialized program that focuses on the study of insects and their impact on public health. This field addresses the role of insects as vectors of diseases and emphasizes strategies to control or manage these diseases within populations', 'master.jpg', 1, 4, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(13, 'MSc Control of Infectious Diseases', 'An MSc (Master of Science) in Control of Infectious Diseases is a specialized program designed to provide a comprehensive understanding of infectious diseases and strategies for their prevention, control, and management. ', 'master.jpg', 1, 4, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(14, 'MSc International Health', 'An MSc (Master of Science) in International Health is a multidisciplinary program that focuses on health-related issues affecting populations globally. This program typically covers various aspects of public health, healthcare systems, and health disparities on an international scale.', 'master.jpg', 1, 4, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(15, 'MSc Epidemiology', 'An MSc (Master of Science) in Epidemiology is a specialized program that focuses on the study of the distribution, determinants, and patterns of diseases within populations. This field involves investigating the causes and factors influencing the occurrence and spread of diseases to inform public health policies and interventions. ', 'master.jpg', 1, 4, '2023-12-26 09:42:26', '2023-12-26 09:42:26'),
	(16, 'MSc Public Health', 'An MSc (Master of Science) in Public Health is a comprehensive program that equips students with the knowledge, skills, and tools needed to address public health challenges and promote population health.', 'master.jpg', 1, 4, '2023-12-26 09:42:26', '2023-12-26 09:42:26');

